struct Budget {
    initial: usize,
    remaining: Cell<usize>,
    floor: Cell<usize>,
    overflowed: Cell<bool>,
    first_refusal: Cell<Option<ReservationRefusal>>,
    stage: Cell<Option<ReservationStage>>,
}

thread_local! {
    static ACTIVE: RefCell<Option<Rc<Budget>>> = const { RefCell::new(None) };
}

pub(crate) fn with_limit<T>(limit: usize, operation: impl FnOnce() -> T) -> (T, bool) {
    let (value, overflowed, _) = with_limit_usage(limit, operation);
    (value, overflowed)
}

pub(crate) fn with_limit_usage<T>(limit: usize, operation: impl FnOnce() -> T) -> (T, bool, usize) {
    let (value, overflowed, consumed, _) = with_limit_usage_refusal(limit, operation);
    (value, overflowed, consumed)
}

pub(crate) fn with_limit_usage_refusal<T>(
    limit: usize,
    operation: impl FnOnce() -> T,
) -> (T, bool, usize, Option<ReservationRefusal>) {
    struct Restore {
        previous: Option<Rc<Budget>>,
        current: Rc<Budget>,
        initial: usize,
    }
    impl Drop for Restore {
        fn drop(&mut self) {
            let consumed = self.initial.saturating_sub(self.current.remaining.get());
            let previous = self.previous.take();
            ACTIVE.with(|active| {
                active.replace(previous.clone());
            });
            if let Some(parent) = previous {
                if !reserve(Some(&parent), consumed) {
                    record_refusal(&parent, consumed);
                    // A refused reservation normally means nothing was
                    // written, but here the child already emitted the bytes:
                    // they cannot be un-spent. Charge the parent anyway, so
                    // `consumed` and `active_remaining` stay truthful, and
                    // report the refusal.
                    let remaining = parent.remaining.get();
                    parent.remaining.set(remaining.saturating_sub(consumed));
                    #[cfg(test)]
                    stage_debits::debit(&parent, remaining.min(consumed));
                    parent.overflowed.set(true);
                }
            }
        }
    }
    let parent = active();
    let effective_limit = parent
        .as_ref()
        .map_or(limit, |budget| limit.min(budget.remaining.get()));
    let budget = Rc::new(Budget {
        initial: effective_limit,
        remaining: Cell::new(effective_limit),
        floor: Cell::new(0),
        overflowed: Cell::new(false),
        first_refusal: Cell::new(None),
        stage: Cell::new(None),
    });
    let previous = ACTIVE.with(|active| active.replace(Some(Rc::clone(&budget))));
    let restore = Restore {
        previous,
        current: Rc::clone(&budget),
        initial: effective_limit,
    };
    let value = operation();
    let overflowed = budget.overflowed.get();
    let consumed = effective_limit.saturating_sub(budget.remaining.get());
    let refusal = budget.first_refusal.get();
    drop(restore);
    (value, overflowed, consumed, refusal)
}

fn active() -> Option<Rc<Budget>> {
    ACTIVE.with(|active| active.borrow().clone())
}

fn record_refusal(budget: &Budget, length: usize) {
    if budget.first_refusal.get().is_none() {
        #[cfg(test)]
        stage_debits::refusal(budget, length);
        budget.first_refusal.set(Some(ReservationRefusal {
            requested: length,
            remaining: budget.remaining.get(),
            floor: budget.floor.get(),
            stage: budget.stage.get(),
        }));
    }
}

/// A stage belongs to the current budget only. Nested budgets start unlabelled,
/// and unwind restores the previous stage before the next reservation.
pub(crate) fn with_reservation_stage<T>(
    stage: ReservationStage,
    operation: impl FnOnce() -> T,
) -> T {
    let restore = reservation_stage_guard(stage);
    let value = operation();
    drop(restore);
    value
}

/// Fixed-size restoration handle. Cloning the existing budget Rc allocates no
/// backing, and the handle never changes budget ownership or refusal selection.
pub(crate) struct ReservationStageGuard(Option<(Rc<Budget>, Option<ReservationStage>)>);
impl Drop for ReservationStageGuard {
    fn drop(&mut self) {
        if let Some((budget, previous)) = self.0.take() {
            budget.stage.set(previous);
        }
    }
}
pub(crate) fn reservation_stage_guard(stage: ReservationStage) -> ReservationStageGuard {
    ReservationStageGuard(active().map(|budget| {
        let previous = budget.stage.replace(Some(stage));
        (budget, previous)
    }))
}

/// Classify only the otherwise unlabelled outer loan-storage operation. An
/// existing semantic phase always wins; no new owner, state or debit is made.
pub(crate) fn loan_allocation_stage_guard(stage: ReservationStage) -> ReservationStageGuard {
    ReservationStageGuard(active().and_then(|budget| {
        if budget.stage.get() != Some(ReservationStage::CanonicalLoanStorage) {
            return None;
        }
        let previous = budget.stage.replace(Some(stage));
        Some((budget, previous))
    }))
}

macro_rules! staged {
    ($stage:ident, $operation:expr) => {
        $crate::bounded_output::with_reservation_stage(
            $crate::bounded_output::ReservationStage::$stage,
            || $operation,
        )
    };
}
pub(crate) use staged;

fn reserve(budget: Option<&Budget>, length: usize) -> bool {
    if budget.is_some_and(|budget| budget.overflowed.get()) {
        return false;
    }
    reserve_optional(budget, length)
}

fn reserve_optional(budget: Option<&Budget>, length: usize) -> bool {
    let Some(budget) = budget else {
        return true;
    };
    // A zero-sized retry cannot authenticate an already refused account.
    // Positive optional writes can still consume a reserved error trailer;
    // they never clear the selected refusal or restore required admission.
    if length == 0 && budget.overflowed.get() {
        return false;
    }
    let remaining = budget.remaining.get();
    if length > remaining {
        record_refusal(budget, length);
        budget.overflowed.set(true);
        return false;
    }
    if length
        .checked_add(budget.floor.get())
        .is_none_or(|required| required > remaining)
    {
        return false;
    }
    budget.remaining.set(remaining - length);
    #[cfg(test)]
    stage_debits::debit(budget, length);
    true
}

pub(crate) fn reserve_active(length: usize) -> bool {
    let budget = active();
    reserve_optional(budget.as_deref(), length)
}

/// Required work cannot turn a reserved-floor refusal into successful output.
/// Preserve the ordinary reservation debit while making every refusal sticky.
pub(crate) fn reserve_active_required(length: usize) -> bool {
    let budget = active();
    if budget
        .as_ref()
        .is_some_and(|budget| budget.overflowed.get())
    {
        return false;
    }
    let admitted = reserve(budget.as_deref(), length);
    if !admitted {
        if let Some(budget) = budget {
            record_refusal(&budget, length);
            budget.overflowed.set(true);
        }
    }
    admitted
}

/// Fail a required allocator frontier without manufacturing another allocation
/// request. Already selected receipts and actual debits remain unchanged.
pub(crate) fn refuse_active_required(requested: usize) {
    if let Some(budget) = active() {
        record_refusal(&budget, requested);
        budget.overflowed.set(true);
    }
}

pub(crate) fn reserve_active_preserving(length: usize, floor: usize) -> bool {
    let budget = active();
    let Some(budget) = budget.as_deref() else {
        return true;
    };
    let floor = floor.max(budget.floor.get());
    let Some(required) = length.checked_add(floor) else {
        return false;
    };
    if required > budget.remaining.get() {
        return false;
    }
    reserve_optional(Some(budget), length)
}

pub(crate) fn set_active_floor(floor: usize) -> bool {
    let Some(budget) = active() else {
        return true;
    };
    if floor > budget.remaining.get() {
        return false;
    }
    budget.floor.set(floor);
    true
}

pub(crate) fn clear_active_floor() {
    if let Some(budget) = active() {
        budget.floor.set(0);
    }
}

pub(crate) fn active_remaining() -> Option<usize> {
    active().map(|budget| budget.remaining.get())
}

/// Infallible bounded helpers may return an empty carrier after refusal.
/// Publication boundaries must reject that sticky state even when their
/// surrounding operation otherwise returned success.
pub(crate) fn active_refused() -> bool {
    active().is_some_and(|budget| budget.overflowed.get())
}

pub(crate) fn active_limit() -> Option<usize> {
    active().map(|budget| budget.initial)
}

fn reserve_sink(captured: Option<&Rc<Budget>>, length: usize) -> bool {
    let current = active();
    let budget = current.as_deref().or_else(|| captured.map(Rc::as_ref));
    reserve(budget, length)
}

fn reserve_optional_sink(captured: Option<&Rc<Budget>>, length: usize) -> bool {
    let current = active();
    reserve_optional(
        current.as_deref().or_else(|| captured.map(Rc::as_ref)),
        length,
    )
}

/// Formats `arguments` in one pass, charging every append to the active
/// budget before it is written.
///
/// Each placeholder's formatter runs exactly once, so a formatter that emits
/// different bytes on different invocations cannot return bytes it was not
/// charged for. A refused append stops formatting. Bytes already appended stay
/// charged: the work was done even though the artifact is discarded.
///
/// Failure is never a successful artifact. A refused append, or a formatter
/// that returns `fmt::Error` after a partial write, yields an empty string and
/// fails the active budget closed through its overflow flag. Outside any
/// budget a formatter error panics, as `std::format!` does, rather than
/// publishing partial text.
pub(crate) fn budgeted_format(arguments: fmt::Arguments<'_>) -> String {
    let budget = active();
    match format_within(budget.as_deref(), arguments) {
        Ok(output) => output,
        Err(FormatFailure::Refused) => String::new(),
        Err(FormatFailure::Formatter) => match budget {
            Some(budget) => {
                budget.overflowed.set(true);
                String::new()
            }
            None => panic!("a formatting trait implementation returned an error"),
        },
    }
}

/// Why single-pass formatting produced no artifact.
#[derive(Debug, PartialEq, Eq)]
enum FormatFailure {
    /// The budget refused an append. `reserve` has already recorded whether
    /// that refusal was an overflow or a reserved-floor boundary.
    Refused,
    /// A formatter returned `fmt::Error` on its own.
    Formatter,
}

fn format_within(
    budget: Option<&Budget>,
    arguments: fmt::Arguments<'_>,
) -> Result<String, FormatFailure> {
    struct ReservingWriter<'a> {
        budget: Option<&'a Budget>,
        output: String,
        refused: bool,
    }
    impl fmt::Write for ReservingWriter<'_> {
        fn write_str(&mut self, value: &str) -> fmt::Result {
            if self.refused || !reserve(self.budget, value.len()) {
                self.refused = true;
                return Err(fmt::Error);
            }
            self.output.push_str(value);
            Ok(())
        }
    }
    let mut writer = ReservingWriter {
        budget,
        output: String::new(),
        refused: false,
    };
    match writer.write_fmt(arguments) {
        Ok(()) if !writer.refused => Ok(writer.output),
        _ if writer.refused => Err(FormatFailure::Refused),
        _ => Err(FormatFailure::Formatter),
    }
}

pub(crate) fn budgeted_join(values: impl IntoIterator<Item = String>, separator: &str) -> String {
    let values = values.into_iter().collect::<Vec<_>>();
    join_slices(&values, separator)
}

pub(crate) fn budgeted_clone(value: &str) -> String {
    let budget = active();
    if !reserve(budget.as_deref(), value.len()) {
        return String::new();
    }
    value.to_owned()
}

pub(crate) trait BudgetedJoin {
    fn budgeted_join(&self, separator: &str) -> String;
}

impl<T: AsRef<str>> BudgetedJoin for [T] {
    fn budgeted_join(&self, separator: &str) -> String {
        join_slices(self, separator)
    }
}

fn join_slices<T: AsRef<str>>(values: &[T], separator: &str) -> String {
    let length = values
        .iter()
        .try_fold(0usize, |length, value| {
            length.checked_add(value.as_ref().len())
        })
        .and_then(|length| {
            separator
                .len()
                .checked_mul(values.len().saturating_sub(1))
                .and_then(|separators| length.checked_add(separators))
        });
    let budget = active();
    let Some(length) = length else {
        if let Some(budget) = budget {
            budget.overflowed.set(true);
        }
        return String::new();
    };
    if !reserve(budget.as_deref(), length) {
        return String::new();
    }
    let mut output = String::with_capacity(length);
    for (index, value) in values.iter().enumerate() {
        if index > 0 {
            output.push_str(separator);
        }
        output.push_str(value.as_ref());
    }
    output
}

pub(crate) mod classifier_string;

pub(crate) struct CappedString {
    bytes: String,
    budget: Option<Rc<Budget>>,
}

impl CappedString {
    pub(crate) fn new() -> Self {
        Self {
            bytes: String::new(),
            budget: active(),
        }
    }

    #[cfg(test)]
    pub(crate) fn allocated_capacity(&self) -> usize {
        self.bytes.capacity()
    }

    pub(crate) fn push_str(&mut self, value: &str) {
        if reserve_sink(self.budget.as_ref(), value.len()) {
            self.bytes.push_str(value);
        }
    }

    pub(crate) fn push(&mut self, value: char) {
        if reserve_sink(self.budget.as_ref(), value.len_utf8()) {
            self.bytes.push(value);
        }
    }

    pub(crate) fn into_string(self) -> String {
        self.bytes
    }
}

impl fmt::Write for CappedString {
    fn write_str(&mut self, value: &str) -> fmt::Result {
        self.push_str(value);
        Ok(())
    }
}

pub(crate) struct CappedVec {
    bytes: Vec<u8>,
    budget: Option<Rc<Budget>>,
}

impl CappedVec {
    pub(crate) fn new() -> Self {
        Self {
            bytes: Vec::new(),
            budget: active(),
        }
    }

    pub(crate) fn from_slice(value: &[u8]) -> Self {
        let mut output = Self::new();
        output.extend_from_slice(value);
        output
    }

    pub(crate) fn push(&mut self, value: u8) {
        if reserve_optional_sink(self.budget.as_ref(), 1) {
            self.bytes.push(value);
        }
    }

    pub(crate) fn extend<const N: usize>(&mut self, values: [u8; N]) {
        self.extend_from_slice(&values);
    }

    pub(crate) fn extend_from_slice(&mut self, values: &[u8]) {
        if reserve_optional_sink(self.budget.as_ref(), values.len()) {
            self.bytes.extend_from_slice(values);
        }
    }

    pub(crate) fn len(&self) -> usize {
        self.bytes.len()
    }

    pub(crate) fn into_vec(self) -> Vec<u8> {
        self.bytes
    }
}

impl Deref for CappedVec {
    type Target = [u8];

    fn deref(&self) -> &Self::Target {
        &self.bytes
    }
}

#[cfg(test)]
mod tests {
    use std::panic::{catch_unwind, AssertUnwindSafe};

    use super::{
        active_limit, active_remaining, budgeted_clone, budgeted_format, budgeted_join,
        clear_active_floor, reserve_active, reserve_active_preserving, reserve_active_required,
        set_active_floor, with_limit, with_limit_usage, BudgetedJoin as _, CappedString, CappedVec,
    };

    /// Emits `first` on its first invocation and `later` on every other one,
    /// counting invocations.
    struct Changing {
        calls: std::cell::Cell<usize>,
        first: &'static str,
        later: &'static str,
    }

    impl Changing {
        fn new(first: &'static str, later: &'static str) -> Self {
            Self {
                calls: std::cell::Cell::new(0),
                first,
                later,
            }
        }
    }

    impl std::fmt::Display for Changing {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            let invocation = self.calls.get();
            self.calls.set(invocation + 1);
            f.write_str(if invocation == 0 {
                self.first
            } else {
                self.later
            })
        }
    }

    /// Hides a literal from `format_args!`, which would otherwise inline it
    /// into the template and merge adjacent pieces into one append.
    fn piece(value: &str) -> &str {
        std::hint::black_box(value)
    }

    /// Writes a prefix and then fails, as a broken formatter may.
    struct PartialThenError(&'static str);

    impl std::fmt::Display for PartialThenError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            f.write_str(self.0)?;
            Err(std::fmt::Error)
        }
    }

    #[test]
    fn exact_limit_succeeds_and_over_limit_fails_closed() {
        let (exact, overflowed) = with_limit(4, || {
            let mut output = CappedString::new();
            output.push_str("four");
            output.into_string()
        });
        assert_eq!(exact, "four");
        assert!(!overflowed);

        let (over, overflowed) = with_limit(3, || {
            let mut output = CappedString::new();
            output.push_str("four");
            output.into_string()
        });
        assert_eq!(over, "");
        assert!(overflowed);
    }

    #[test]
    fn join_length_is_checked_and_budgeted() {
        let (joined, overflowed) =
            with_limit(5, || budgeted_join(["ab".to_owned(), "cd".to_owned()], ","));
        assert_eq!(joined, "ab,cd");
        assert!(!overflowed);

        let (joined, overflowed) =
            with_limit(4, || budgeted_join(["ab".to_owned(), "cd".to_owned()], ","));
        assert_eq!(joined, "");
        assert!(overflowed);
    }

    #[test]
    fn nested_budget_debits_parent_and_parent_sink_uses_child() {
        let (_, parent_overflowed) = with_limit(5, || {
            let mut parent_sink = CappedString::new();
            let (_, child_overflowed) = with_limit(3, || parent_sink.push_str("four"));
            assert!(child_overflowed);
            parent_sink.push_str("five!");
            assert_eq!(parent_sink.into_string(), "five!");
        });
        assert!(!parent_overflowed);

        let (_, parent_overflowed) = with_limit(5, || {
            let (_, child_overflowed) = with_limit(4, || {
                let mut output = CappedString::new();
                output.push_str("four");
            });
            assert!(!child_overflowed);
            let mut output = CappedString::new();
            output.push_str("xx");
        });
        assert!(parent_overflowed);
    }

    #[test]
    fn panic_restores_and_debits_parent_budget() {
        let (_, parent_overflowed) = with_limit(5, || {
            let result = catch_unwind(AssertUnwindSafe(|| {
                let _ = with_limit(4, || {
                    let mut output = CappedString::new();
                    output.push_str("four");
                    panic!("injected");
                });
            }));
            assert!(result.is_err());
            let mut output = CappedString::new();
            output.push_str("xx");
        });
        assert!(parent_overflowed);
    }

    #[test]
    fn usage_reports_exact_debits_and_preserves_nested_restoration() {
        let ((child_overflowed, child_used), parent_overflowed, parent_used) =
            with_limit_usage(7, || {
                let (_, child_overflowed, child_used) = with_limit_usage(4, || {
                    let mut output = CappedString::new();
                    output.push_str("abc");
                });
                let mut output = CappedString::new();
                output.push_str("defg");
                (child_overflowed, child_used)
            });
        assert!(!child_overflowed);
        assert_eq!(child_used, 3);
        assert!(!parent_overflowed);
        assert_eq!(parent_used, 7);

        let (_, overflowed, used) = with_limit_usage(2, || {
            let mut output = CappedString::new();
            output.push_str("abc");
        });
        assert!(overflowed);
        assert_eq!(used, 0);

        let (_, overflowed, used) = with_limit_usage(3, || {
            let mut output = CappedString::new();
            output.push_str("xyz");
        });
        assert!(!overflowed);
        assert_eq!(used, 3);
    }

    #[test]
    fn zero_and_one_byte_budgets_admit_only_what_fits() {
        // A zero budget still admits an empty write: nothing is spent, so
        // nothing overflows. The first byte is what fails.
        let (empty, overflowed, used) = with_limit_usage(0, || {
            let mut output = CappedString::new();
            output.push_str("");
            output.into_string()
        });
        assert_eq!(empty, "");
        assert!(!overflowed);
        assert_eq!(used, 0);

        let (nothing, overflowed) = with_limit(0, || {
            let mut output = CappedString::new();
            output.push('a');
            output.into_string()
        });
        assert_eq!(nothing, "");
        assert!(overflowed);

        let (one, overflowed, used) = with_limit_usage(1, || {
            let mut output = CappedString::new();
            output.push('a');
            output.into_string()
        });
        assert_eq!(one, "a");
        assert!(!overflowed);
        assert_eq!(used, 1);

        let (over, overflowed) = with_limit(1, || {
            let mut output = CappedString::new();
            output.push_str("ab");
            output.into_string()
        });
        assert_eq!(over, "");
        assert!(overflowed);
    }

    #[test]
    fn budgets_count_bytes_and_never_split_a_code_point() {
        // `é` is two bytes and `€` is three: a three-byte budget admits the
        // first and must refuse the second whole rather than write a prefix
        // of its encoding.
        let (output, overflowed) = with_limit(3, || {
            let mut output = CappedString::new();
            output.push('é');
            output.push('€');
            output.into_string()
        });
        assert_eq!(output, "é");
        assert_eq!(output.len(), 2);
        assert!(overflowed);
        assert_eq!(output.chars().count(), 1);

        // Two characters, four bytes: the budget is spent in bytes, so a
        // three-byte budget refuses the string outright.
        let (output, overflowed) = with_limit(3, || {
            let mut output = CappedString::new();
            output.push_str("éé");
            output.into_string()
        });
        assert_eq!(output, "");
        assert!(overflowed);

        // A four-byte code point does not fit a three-byte budget at all.
        let (output, overflowed) = with_limit(3, || {
            let mut output = CappedString::new();
            output.push('\u{1f600}');
            output.into_string()
        });
        assert_eq!(output, "");
        assert!(overflowed);

        let (output, overflowed, used) = with_limit_usage(4, || {
            let mut output = CappedString::new();
            output.push('\u{1f600}');
            output.into_string()
        });
        assert_eq!(output, "\u{1f600}");
        assert!(!overflowed);
        assert_eq!(used, 4);
    }

    #[test]
    fn capped_vec_writes_are_all_or_nothing_and_leave_the_budget_usable() {
        let (bytes, overflowed) = with_limit(5, || {
            let mut output = CappedVec::new();
            // Six bytes into five: the whole slice is refused, not a prefix.
            output.extend_from_slice(&[1, 2, 3, 4, 5, 6]);
            assert!(output.is_empty());
            // The refusal spent nothing, so the budget still admits writes.
            output.extend([7, 8]);
            output.push(9);
            assert_eq!(output.len(), 3);
            assert_eq!(&output[..], &[7u8, 8, 9][..]);
            output.into_vec()
        });
        assert_eq!(bytes, vec![7, 8, 9]);
        assert!(overflowed);

        let (bytes, overflowed, used) =
            with_limit_usage(3, || CappedVec::from_slice(&[1, 2, 3]).into_vec());
        assert_eq!(bytes, vec![1, 2, 3]);
        assert!(!overflowed);
        assert_eq!(used, 3);

        let (bytes, overflowed) = with_limit(2, || CappedVec::from_slice(&[1, 2, 3]).into_vec());
        assert!(bytes.is_empty());
        assert!(overflowed);
    }

    #[test]
    fn a_floor_reserves_a_trailer_lane_without_reporting_overflow() {
        let (_, overflowed, used) = with_limit_usage(10, || {
            assert!(set_active_floor(6));
            // Five bytes fit the remaining ten but would eat into the six
            // reserved for the trailer, so the reservation is refused. That
            // refusal is a lane boundary, not a budget overflow.
            assert!(!reserve_active(5));
            assert_eq!(active_remaining(), Some(10));
            assert!(reserve_active(4));
            assert_eq!(active_remaining(), Some(6));
            assert!(!reserve_active(1));

            clear_active_floor();
            assert!(reserve_active(6));
            assert_eq!(active_remaining(), Some(0));
        });
        assert!(!overflowed);
        assert_eq!(used, 10);

        // A floor larger than what remains is refused and leaves the previous
        // floor in place, so the caller cannot silently arm an unsatisfiable
        // reservation.
        let (_, overflowed) = with_limit(10, || {
            assert!(!set_active_floor(11));
            assert!(reserve_active(10));
        });
        assert!(!overflowed);
    }

    #[test]
    fn preserving_reservations_check_a_trailer_without_arming_the_floor() {
        let (_, overflowed) = with_limit(7, || {
            // Three bytes plus a five-byte trailer exceed seven, so the write
            // is refused and nothing is spent.
            assert!(!reserve_active_preserving(3, 5));
            assert_eq!(active_remaining(), Some(7));
            assert!(reserve_active_preserving(2, 5));
            assert_eq!(active_remaining(), Some(5));
            // The declared trailer was a per-call check, not a persistent
            // floor: an ordinary reservation may still spend the remainder.
            assert!(reserve_active(5));
            assert_eq!(active_remaining(), Some(0));
        });
        assert!(!overflowed);
    }

    #[test]
    fn required_reservations_admit_exact_bytes_and_refuse_one_short() {
        let (admitted, overflowed, used) = with_limit_usage(4, || reserve_active_required(4));
        assert!(admitted);
        assert!(!overflowed);
        assert_eq!(used, 4);

        let (admitted, overflowed, used) = with_limit_usage(3, || reserve_active_required(4));
        assert!(!admitted);
        assert!(overflowed);
        assert_eq!(used, 0);
        assert!(reserve_active_required(usize::MAX));
    }

    #[test]
    fn required_floor_refusal_stays_failed_after_the_trailer_is_written() {
        let (_, overflowed, used) = with_limit_usage(10, || {
            assert!(set_active_floor(6));
            assert!(reserve_active_required(4));
            assert_eq!(active_remaining(), Some(6));
            assert!(!reserve_active_required(1));
            assert_eq!(active_remaining(), Some(6));
            clear_active_floor();
            assert!(reserve_active(6));
        });
        assert!(overflowed);
        assert_eq!(used, 10);
    }

    #[test]
    fn reservations_outside_any_budget_always_succeed() {
        assert_eq!(active_remaining(), None);
        assert_eq!(active_limit(), None);
        assert!(reserve_active(usize::MAX));
        assert!(reserve_active_preserving(usize::MAX, usize::MAX));
        assert!(set_active_floor(usize::MAX));
        clear_active_floor();
        assert_eq!(budgeted_clone("unbounded"), "unbounded");
    }

    #[test]
    fn a_nested_limit_is_clamped_to_what_the_parent_has_left() {
        let (inner, overflowed) = with_limit(5, || {
            let mut output = CappedString::new();
            output.push_str("ab");
            // The child asks for a hundred bytes but may not exceed the three
            // its parent still holds.
            with_limit(100, || (active_limit(), active_remaining())).0
        });
        assert_eq!(inner, (Some(3), Some(3)));
        assert!(!overflowed);

        // The clamp is real, not merely reported: the child cannot emit more
        // than the parent's remainder, and its refusal is reported to the
        // child's own caller without spending parent bytes.
        let ((child, child_overflowed), overflowed, used) = with_limit_usage(5, || {
            let mut parent = CappedString::new();
            parent.push_str("ab");
            with_limit(100, || {
                let mut output = CappedString::new();
                output.push_str("cdef");
                output.into_string()
            })
        });
        assert_eq!(child, "");
        assert!(child_overflowed);
        assert!(!overflowed);
        assert_eq!(used, 2);
    }

    #[test]
    fn a_child_that_would_consume_the_parents_floor_fails_the_parent_closed() {
        let (_, overflowed) = with_limit(10, || {
            assert!(set_active_floor(8));
            let (_, child_overflowed) = with_limit(4, || {
                let mut output = CappedString::new();
                output.push_str("abcd");
            });
            // The child stayed inside its own limit, so it reports no
            // overflow; the parent debits the child on scope exit, discovers
            // the bytes would eat its reserved trailer, and fails closed.
            assert!(!child_overflowed);
        });
        assert!(overflowed);
    }

    #[test]
    fn a_child_that_breaches_the_parents_floor_is_still_charged_to_the_parent() {
        // Failing closed is only half the accounting. The child has already
        // emitted its bytes by the time the parent debits them, so a refused
        // debit cannot un-spend them: the parent must lose them as well as
        // overflow, or `consumed` undercounts and `active_remaining` overstates
        // what a caller may still write.
        let (_, overflowed, used) = with_limit_usage(10, || {
            assert!(set_active_floor(8));
            let (emitted, child_overflowed, child_used) = with_limit_usage(4, || {
                let mut output = CappedString::new();
                output.push_str("abcd");
                output.into_string()
            });
            assert_eq!(emitted, "abcd");
            assert!(!child_overflowed);
            assert_eq!(child_used, 4);
            assert_eq!(active_remaining(), Some(6));
        });
        assert!(overflowed);
        assert_eq!(used, 4);

        // The debited remainder is real rather than a bookkeeping entry: once
        // the trailer lane is released the parent may spend exactly the six
        // bytes it has left and not one more.
        let (_, overflowed, used) = with_limit_usage(10, || {
            assert!(set_active_floor(8));
            let (_, child_overflowed) = with_limit(4, || {
                let mut output = CappedString::new();
                output.push_str("abcd");
            });
            assert!(!child_overflowed);
            clear_active_floor();
            assert!(!reserve_active(7));
            assert!(reserve_active(6));
            assert_eq!(active_remaining(), Some(0));
        });
        assert!(overflowed);
        assert_eq!(used, 10);
    }

    #[test]
    fn identical_input_and_budget_produce_identical_output_after_an_overflow() {
        fn render(limit: usize) -> (String, bool) {
            with_limit(limit, || {
                let mut output = CappedString::new();
                output.push_str(&budgeted_format(format_args!("{}-{}", "café", 42)));
                output.push('!');
                output.into_string()
            })
        }

        let first = render(20);
        let (partial, flagged) = render(3);
        assert!(flagged);
        assert!(partial.len() <= 3, "{partial:?} exceeded its budget");
        // A prior overflow must not leave thread-local budget state behind.
        assert_eq!(active_remaining(), None);
        let second = render(20);
        assert_eq!(first.0.as_bytes(), second.0.as_bytes());
        assert_eq!(first.1, second.1);
        assert!(!first.1);
    }

    #[test]
    fn formatting_and_cloning_charge_exact_byte_lengths() {
        // `café-42` is eight bytes: the accented byte counts, and the exact
        // budget succeeds while one byte less refuses the whole string.
        let (formatted, overflowed, used) =
            with_limit_usage(8, || budgeted_format(format_args!("{}-{}", "café", 42)));
        assert_eq!(formatted, "café-42");
        assert!(!overflowed);
        assert_eq!(used, 8);

        let (formatted, overflowed) =
            with_limit(7, || budgeted_format(format_args!("{}-{}", "café", 42)));
        assert_eq!(formatted, "");
        assert!(overflowed);

        let (cloned, overflowed, used) = with_limit_usage(3, || budgeted_clone("abc"));
        assert_eq!(cloned, "abc");
        assert!(!overflowed);
        assert_eq!(used, 3);

        let (cloned, overflowed) = with_limit(2, || budgeted_clone("abc"));
        assert_eq!(cloned, "");
        assert!(overflowed);
    }

    #[test]
    fn joins_charge_one_separator_fewer_than_their_elements() {
        let (joined, overflowed, used) =
            with_limit_usage(0, || budgeted_join(Vec::<String>::new(), ",,,,"));
        assert_eq!(joined, "");
        assert!(!overflowed);
        assert_eq!(used, 0);

        // A single element pays for no separator at all.
        let (joined, overflowed, used) =
            with_limit_usage(3, || budgeted_join(["abc".to_owned()], ",,,,"));
        assert_eq!(joined, "abc");
        assert!(!overflowed);
        assert_eq!(used, 3);

        let (joined, overflowed, used) = with_limit_usage(4, || ["a", "b"].budgeted_join("--"));
        assert_eq!(joined, "a--b");
        assert!(!overflowed);
        assert_eq!(used, 4);

        let (joined, overflowed) = with_limit(3, || ["a", "b"].budgeted_join("--"));
        assert_eq!(joined, "");
        assert!(overflowed);
    }

    #[test]
    fn a_stateful_formatter_runs_once_and_cannot_return_uncharged_bytes() {
        let value = Changing::new("x", "0123456789");
        let (text, overflowed, used) =
            with_limit_usage(1, || budgeted_format(format_args!("{value}")));
        assert_eq!(text, "x");
        assert!(!overflowed);
        assert_eq!(used, 1);
        assert_eq!(value.calls.get(), 1);

        // Ten bytes on the first and only invocation are refused under the
        // same one-byte limit.
        let value = Changing::new("0123456789", "x");
        let (text, overflowed, used) =
            with_limit_usage(1, || budgeted_format(format_args!("{value}")));
        assert_eq!(text, "");
        assert!(overflowed);
        assert_eq!(used, 0);
        assert_eq!(value.calls.get(), 1);
    }

    #[test]
    fn formatting_at_the_cap_succeeds_and_one_byte_over_fails_closed() {
        let (text, overflowed, used) = with_limit_usage(3, || {
            budgeted_format(format_args!("{}{}", piece("ab"), piece("c")))
        });
        assert_eq!(text, "abc");
        assert!(!overflowed);
        assert_eq!(used, 3);

        // Cap plus one: the first append fits and stays charged, the second
        // is refused, formatting stops and no partial text is returned.
        let later = Changing::new("never", "never");
        let (text, overflowed, used) = with_limit_usage(2, || {
            budgeted_format(format_args!("{}{}{}", piece("ab"), piece("c"), later))
        });
        assert_eq!(text, "");
        assert!(overflowed);
        assert_eq!(used, 2);
        assert_eq!(
            later.calls.get(),
            0,
            "a refused append must stop formatting"
        );
    }

    #[test]
    fn empty_formatting_spends_nothing_even_under_a_zero_budget() {
        let (text, overflowed, used) = with_limit_usage(0, || budgeted_format(format_args!("")));
        assert_eq!(text, "");
        assert!(!overflowed);
        assert_eq!(used, 0);

        let (text, overflowed, used) = with_limit_usage(0, || {
            budgeted_format(format_args!("{}{}", piece(""), piece("")))
        });
        assert_eq!(text, "");
        assert!(!overflowed);
        assert_eq!(used, 0);
    }

    #[test]
    fn multibyte_formatting_charges_bytes_and_never_splits_a_code_point() {
        let (text, overflowed, used) =
            with_limit_usage(5, || budgeted_format(format_args!("{}{}", 'é', '€')));
        assert_eq!(text, "é€");
        assert!(!overflowed);
        assert_eq!(used, 5);

        // `é` (two bytes) fits a four-byte budget, `€` (three bytes) does not
        // fit the two that remain: it is refused whole and nothing returned.
        let (text, overflowed, used) =
            with_limit_usage(4, || budgeted_format(format_args!("{}{}", 'é', '€')));
        assert_eq!(text, "");
        assert!(overflowed);
        assert_eq!(used, 2);
    }

    #[test]
    fn a_formatter_error_after_a_partial_write_is_never_a_success() {
        let (text, overflowed, used) = with_limit_usage(10, || {
            budgeted_format(format_args!("{}{}", piece("<"), PartialThenError("ab")))
        });
        assert_eq!(text, "");
        assert!(overflowed, "a formatter error must fail the budget closed");
        assert_eq!(used, 3, "bytes already appended stay charged");

        // Outside any budget there is no flag to fail closed, so the error
        // panics as `std::format!` does instead of returning partial text.
        let result = catch_unwind(|| budgeted_format(format_args!("{}", PartialThenError("ab"))));
        assert!(result.is_err());
        assert_eq!(active_remaining(), None);
    }

    #[test]
    fn nested_formatting_failures_stay_in_the_child_and_debit_the_parent() {
        let ((text, child_overflowed, child_used), parent_overflowed, parent_used) =
            with_limit_usage(10, || {
                with_limit_usage(3, || {
                    budgeted_format(format_args!("{}{}", piece("ab"), piece("cd")))
                })
            });
        assert_eq!(text, "");
        assert!(child_overflowed);
        assert_eq!(child_used, 2);
        assert!(!parent_overflowed);
        assert_eq!(parent_used, 2);

        let ((text, child_overflowed), parent_overflowed, parent_used) =
            with_limit_usage(10, || {
                with_limit(10, || {
                    budgeted_format(format_args!("{}", PartialThenError("a")))
                })
            });
        assert_eq!(text, "");
        assert!(child_overflowed);
        assert!(!parent_overflowed);
        assert_eq!(parent_used, 1);
    }

    #[test]
    fn formatting_into_a_reserved_floor_is_a_lane_refusal_not_an_overflow() {
        let (_, overflowed, used) = with_limit_usage(10, || {
            assert!(set_active_floor(6));
            // `abc` fits above the six-byte trailer lane; `de` would eat into
            // it. The append is refused without an overflow, the charged
            // prefix is kept, and the lane itself is untouched.
            let text = budgeted_format(format_args!("{}{}", piece("abc"), piece("de")));
            assert_eq!(text, "");
            assert_eq!(active_remaining(), Some(7));
            clear_active_floor();
        });
        assert!(!overflowed);
        assert_eq!(used, 3);
    }
}

#[cfg(test)]
mod refusal_tests;

#[cfg(test)]
mod resolution_stage_tests;

mod source_owner_scope;
pub(crate) use source_owner_scope::source_owner_scope;

#[cfg(test)]
mod canonical_stage_tests;

#[cfg(test)]
mod loan_inner_stage_tests;

edits.new:
//! Target-neutral capacity authority for Portable Indexed Byte Data v1.
//!
//! This module deliberately consumes a small, identity-bearing projection
//! instead of backend storage. Source verification and hostile-HIR validation
//! can build the projection independently and must obtain the same summaries.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt;

pub(crate) const MAX_ARRAY_BYTES: u64 = 65_536;
pub(crate) const MAX_INLINE_ARRAY_FRAME_BYTES: u64 = 65_536;
pub(crate) const MAX_ACTIVE_ARRAY_CALL_PATH_BYTES: u64 = 65_536;
pub(crate) const MAX_BYTES_COPY_SITES: u32 = 32;
pub(crate) const MAX_OWNED_BYTE_PAYLOAD_BYTES: u64 = 2_097_152;
pub(crate) const MAX_STDOUT_TRANSCRIPT_BYTES: u64 = 65_536;
pub(crate) const MAX_STDOUT_WRITES_PER_PATH: u64 = 1;
pub(crate) const MAX_STDERR_WRITES_PER_PATH: u64 = 1;
pub(crate) const MAX_STDIN_READS_PER_PATH: u64 = 1;
pub(crate) const MAX_COMBINED_TRANSCRIPT_BYTES: u64 = 65_536;

pub(crate) const MAX_FUNCTIONS: usize = 4_096;
const MAX_FLOW_NODES: usize = 65_536;
const MAX_ARRAY_SLOTS_PER_FUNCTION: usize = 65_536;

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(crate) enum ArrayStorageKind {
    Parameter,
    Binding,
    Temporary,
    CallStaging,
    ProvisionalResult,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ArrayStorageSlot {
    pub identity: String,
    pub kind: ArrayStorageKind,
    pub length: u32,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum CapacityFlow {
    Empty,
    Sequence(Vec<CapacityFlow>),
    Alternative(Vec<CapacityFlow>),
    Call {
        site: String,
        callee: String,
    },
    BytesCopy {
        site: String,
        conservative_payload_bytes: u64,
    },
    StdinRead {
        site: String,
        conservative_payload_bytes: u64,
    },
    StdoutWrite {
        site: String,
        source: TranscriptSource,
    },
    StderrWrite {
        site: String,
        source: TranscriptSource,
    },
    /// Runtime-bounded transcript publication. Unlike the legacy write
    /// operations, an append may execute repeatedly; the command runtime owns
    /// the exact cumulative `MAX_COMBINED_TRANSCRIPT_BYTES` check.
    StdoutAppend {
        site: String,
    },
    StderrAppend {
        site: String,
    },
    Loop {
        condition: Box<CapacityFlow>,
        body: Box<CapacityFlow>,
    },
    /// Supplied only by independent source/HIR owned-iterator provenance.
    FiniteOwnedLoop {
        iterations: u32,
        condition: Box<CapacityFlow>,
        body: Box<CapacityFlow>,
    },
    /// One fused construction loop under the explicit
    /// [`AllocationStrategy::FusedConstructionV1`]. It charges exactly one
    /// backing event and `rows * width` payload bytes; `producer` names the
    /// body's single `BytesCopy` site. The flow records a selection. It does
    /// not prove count, destination, fresh row or escape facts.
    #[cfg_attr(
        not(test),
        allow(
            dead_code,
            reason = "constructed only by the pending source/HIR fused selectors"
        )
    )]
    FusedConstruction {
        producer: String,
        rows: u32,
        width: u64,
        condition: Box<CapacityFlow>,
        body: Box<CapacityFlow>,
    },
}

/// Explicit, versioned allocation strategy selected by the analyzing entry.
/// [`analyze`] always uses `Legacy`; no flow, cache or graph fact selects one.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum AllocationStrategy {
    Legacy,
    #[cfg_attr(
        not(test),
        allow(
            dead_code,
            reason = "selected only by the pending source/HIR fused entries"
        )
    )]
    FusedConstructionV1,
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(crate) enum TranscriptSource {
    Fixed(u64),
    CommandArguments,
    Stdin,
    Unknown,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct FunctionCapacityInput {
    pub function: String,
    pub array_slots: Vec<ArrayStorageSlot>,
    pub execution: CapacityFlow,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct FunctionCapacitySummary {
    pub inline_array_frame_bytes: u64,
    pub active_array_call_path_bytes: u64,
    pub bytes_copy_sites: u32,
    pub owned_byte_payload_bytes: u64,
    pub stdin_read_sites: u64,
    pub stdout_write_sites: u64,
    pub stderr_write_sites: u64,
    pub stdout_append_sites: u64,
    pub stderr_append_sites: u64,
    pub transcript_bytes: u64,
    /// Fused backing events already included in `bytes_copy_sites`.
    #[cfg_attr(
        not(test),
        allow(
            dead_code,
            reason = "read by the pending fused refusal and executor lanes"
        )
    )]
    pub fused_backing_events: u32,
    transcript_paths: Vec<TranscriptPath>,
}

impl Default for FunctionCapacitySummary {
    fn default() -> Self {
        Self {
            inline_array_frame_bytes: 0,
            active_array_call_path_bytes: 0,
            bytes_copy_sites: 0,
            fused_backing_events: 0,
            owned_byte_payload_bytes: 0,
            stdin_read_sites: 0,
            stdout_write_sites: 0,
            stderr_write_sites: 0,
            stdout_append_sites: 0,
            stderr_append_sites: 0,
            transcript_bytes: 0,
            transcript_paths: vec![TranscriptPath::default()],
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ProgramCapacitySummary {
    strategy: AllocationStrategy,
    functions: BTreeMap<String, FunctionCapacitySummary>,
}

impl ProgramCapacitySummary {
    #[cfg_attr(
        not(test),
        allow(
            dead_code,
            reason = "read by the pending fused refusal and executor lanes"
        )
    )]
    pub(crate) fn strategy(&self) -> AllocationStrategy {
        self.strategy
    }

    pub(crate) fn function(&self, identity: &str) -> Option<&FunctionCapacitySummary> {
        self.functions.get(identity)
    }

    pub(crate) fn functions(
        &self,
    ) -> impl ExactSizeIterator<Item = (&str, &FunctionCapacitySummary)> {
        self.functions
            .iter()
            .map(|(identity, summary)| (identity.as_str(), summary))
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum CapacityDiagnostic {
    Array,
    Allocation,
    Transcript,
    Invariant,
}

impl CapacityDiagnostic {
    pub(crate) const fn code(self) -> &'static str {
        match self {
            Self::Array => "SPX-T261",
            Self::Allocation => "SPX-T267",
            Self::Transcript => "SPX-T269",
            Self::Invariant => "SPX-H006",
        }
    }
}

#[derive(Debug, Eq, PartialEq)]
pub(crate) struct CapacityError {
    pub diagnostic: CapacityDiagnostic,
    pub function: Option<String>,
    pub detail: String,
    pub witness_help: Option<String>,
}

impl Clone for CapacityError {
    fn clone(&self) -> Self {
        Self {
            diagnostic: self.diagnostic,
            function: self.function.clone(),
            detail: self.detail.clone(),
            // The original primary clones stay unchanged. Optional new owned
            // help is acquired only through its independently paid constructor.
            witness_help: self.witness_help.as_deref().and_then(witnesses::clone_help),
        }
    }
}

impl fmt::Display for CapacityError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(function) = &self.function {
            write!(
                formatter,
                "{} in `{function}`: {}",
                self.diagnostic.code(),
                self.detail
            )
        } else {
            write!(formatter, "{}: {}", self.diagnostic.code(), self.detail)
        }
    }
}

impl std::error::Error for CapacityError {}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct AllocationSummary {
    sites: u32,
    stdin_sites: u64,
    payload_bytes: u64,
    fused: u32,
}

#[derive(Clone, Debug, Default, Eq, Ord, PartialEq, PartialOrd)]
struct TranscriptPath {
    stdout_sites: u64,
    stderr_sites: u64,
    stdout_append_sites: u64,
    stderr_append_sites: u64,
    indirect_append_sites: u64,
    sources: Vec<TranscriptSource>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct TranscriptSummary {
    paths: Vec<TranscriptPath>,
}

impl Default for TranscriptSummary {
    fn default() -> Self {
        Self {
            paths: vec![TranscriptPath::default()],
        }
    }
}

#[derive(Clone, Copy)]
enum FoldMode {
    Array,
    Allocation,
    Transcript,
}

struct ValidatedFunction<'a> {
    input: &'a FunctionCapacityInput,
    frame_bytes: u64,
    callees: BTreeSet<&'a str>,
    has_local_copy: bool,
    has_local_stdin_read: bool,
    has_local_transcript_write: bool,
}

/// The unchanged default: `Legacy`, under which a fused flow is an invariant.
pub(crate) fn analyze(
    functions: &[FunctionCapacityInput],
) -> Result<ProgramCapacitySummary, CapacityError> {
    analyze_with_strategy(functions, AllocationStrategy::Legacy)
}

/// Selected analysis entry. A non-`Legacy` strategy only admits its own flow
/// node. Every existing per-path and per-value limit still applies.
pub(crate) fn analyze_with_strategy(
    functions: &[FunctionCapacityInput],
    strategy: AllocationStrategy,
) -> Result<ProgramCapacitySummary, CapacityError> {
    if functions.len() > MAX_FUNCTIONS {
        return Err(invariant(
            None,
            "byte-data capacity function count exceeds the compiler bound",
        ));
    }
    let mut by_id = BTreeMap::<&str, &FunctionCapacityInput>::new();
    for function in functions {
        require_identity(&function.function, None, "function")?;
        if by_id.insert(&function.function, function).is_some() {
            return Err(invariant(
                Some(&function.function),
                "duplicate function identity in byte-data capacity input",
            ));
        }
    }

    let mut validated = BTreeMap::<&str, ValidatedFunction<'_>>::new();
    for (identity, function) in &by_id {
        let frame_bytes = validate_slots(function)?;
        let (callees, has_local_copy, has_local_stdin_read, has_local_transcript_write) =
            validate_flow(function, &by_id, strategy)?;
        validated.insert(
            identity,
            ValidatedFunction {
                input: function,
                frame_bytes,
                callees,
                has_local_copy,
                has_local_stdin_read,
                has_local_transcript_write,
            },
        );
    }

    let array_relevant = reverse_reachable(&validated, |item| item.frame_bytes != 0);
    let allocation_relevant = reverse_reachable(&validated, |item| {
        item.has_local_copy || item.has_local_stdin_read
    });
    let transcript_relevant = reverse_reachable(&validated, |item| item.has_local_transcript_write);
    let array_order =
        relevant_topological_order(&validated, &array_relevant, CapacityDiagnostic::Array)?;
    let allocation_order = relevant_topological_order(
        &validated,
        &allocation_relevant,
        CapacityDiagnostic::Allocation,
    )?;
    let transcript_order = relevant_topological_order(
        &validated,
        &transcript_relevant,
        CapacityDiagnostic::Transcript,
    )?;

    let mut summaries = validated
        .iter()
        .map(|(identity, item)| {
            (
                (*identity).to_owned(),
                FunctionCapacitySummary {
                    inline_array_frame_bytes: item.frame_bytes,
                    ..FunctionCapacitySummary::default()
                },
            )
        })
        .collect::<BTreeMap<_, _>>();

    for identity in array_order.into_iter().rev() {
        let item = &validated[identity];
        let child_bytes = fold_flow(
            &item.input.execution,
            FoldMode::Array,
            identity,
            &summaries,
            &by_id,
        )?
        .0;
        let active = item.frame_bytes.checked_add(child_bytes).ok_or_else(|| {
            array_error(
                identity,
                "active array call-path byte calculation overflowed",
            )
        })?;
        if active > MAX_ACTIVE_ARRAY_CALL_PATH_BYTES {
            return Err(array_error(
                identity,
                format!(
                    "active array call-path uses {active} bytes; limit is {MAX_ACTIVE_ARRAY_CALL_PATH_BYTES}"
                ),
            ));
        }
        summaries
            .get_mut(identity)
            .expect("validated function has a summary")
            .active_array_call_path_bytes = active;
    }

    for identity in allocation_order.into_iter().rev() {
        let item = &validated[identity];
        let (_, allocation, _) = fold_flow(
            &item.input.execution,
            FoldMode::Allocation,
            identity,
            &summaries,
            &by_id,
        )?;
        if allocation.sites > MAX_BYTES_COPY_SITES {
            return Err(allocation_error(
                identity,
                format!(
                    "bytes_copy path reaches {} sites; limit is {MAX_BYTES_COPY_SITES}",
                    allocation.sites
                ),
            ));
        }
        if allocation.stdin_sites > MAX_STDIN_READS_PER_PATH {
            return Err(allocation_error(
                identity,
                format!(
                    "stdin_read path reaches {} sites; limit is {MAX_STDIN_READS_PER_PATH}",
                    allocation.stdin_sites
                ),
            ));
        }
        if allocation.payload_bytes > MAX_OWNED_BYTE_PAYLOAD_BYTES {
            return Err(allocation_error(
                identity,
                format!(
                    "bytes_copy path admits {} payload bytes; limit is {MAX_OWNED_BYTE_PAYLOAD_BYTES}",
                    allocation.payload_bytes
                ),
            ));
        }
        let summary = summaries
            .get_mut(identity)
            .expect("validated function has a summary");
        summary.bytes_copy_sites = allocation.sites;
        summary.stdin_read_sites = allocation.stdin_sites;
        summary.owned_byte_payload_bytes = allocation.payload_bytes;
        summary.fused_backing_events = allocation.fused;
    }

    for identity in transcript_order.into_iter().rev() {
        let item = &validated[identity];
        let (_, _, transcript) = fold_flow(
            &item.input.execution,
            FoldMode::Transcript,
            identity,
            &summaries,
            &by_id,
        )?;
        let mut stdout_sites = 0;
        let mut stderr_sites = 0;
        let mut stdout_append_sites = 0;
        let mut stderr_append_sites = 0;
        let mut transcript_bytes = 0;
        for path in &transcript.paths {
            if path.stdout_sites > MAX_STDOUT_WRITES_PER_PATH {
                let mut selected = transcript_error(
                    identity,
                    format!(
                        "stdout_write path reaches {} sites; limit is {}",
                        path.stdout_sites, MAX_STDOUT_WRITES_PER_PATH
                    ),
                );
                selected.witness_help = witnesses::repeated(
                    &item.input.execution,
                    identity,
                    &by_id,
                    witnesses::Query::Stdout,
                );
                return Err(selected);
            }
            if path.stderr_sites > MAX_STDERR_WRITES_PER_PATH {
                let mut selected = transcript_error(
                    identity,
                    format!(
                        "stderr_write path reaches {} sites; limit is {}",
                        path.stderr_sites, MAX_STDERR_WRITES_PER_PATH
                    ),
                );
                selected.witness_help = witnesses::repeated(
                    &item.input.execution,
                    identity,
                    &by_id,
                    witnesses::Query::Stderr,
                );
                return Err(selected);
            }
            stdout_sites = stdout_sites.max(path.stdout_sites);
            stderr_sites = stderr_sites.max(path.stderr_sites);
            stdout_append_sites = stdout_append_sites.max(path.stdout_append_sites);
            stderr_append_sites = stderr_append_sites.max(path.stderr_append_sites);
            transcript_bytes = transcript_bytes.max(transcript_path_bytes(identity, path)?);
        }
        let summary = summaries
            .get_mut(identity)
            .expect("validated function has a summary");
        summary.stdout_write_sites = stdout_sites;
        summary.stderr_write_sites = stderr_sites;
        summary.stdout_append_sites = stdout_append_sites;
        summary.stderr_append_sites = stderr_append_sites;
        summary.transcript_bytes = transcript_bytes;
        summary.transcript_paths = transcript.paths;
    }

    Ok(ProgramCapacitySummary {
        strategy,
        functions: summaries,
    })
}

fn validate_slots(function: &FunctionCapacityInput) -> Result<u64, CapacityError> {
    if function.array_slots.len() > MAX_ARRAY_SLOTS_PER_FUNCTION {
        return Err(array_error(
            &function.function,
            "inline array slot count exceeds the compiler bound",
        ));
    }
    let mut identities = BTreeSet::new();
    let mut total = 0u64;
    for slot in &function.array_slots {
        require_identity(
            &slot.identity,
            Some(&function.function),
            "array storage slot",
        )?;
        if !identities.insert(slot.identity.as_str()) {
            return Err(invariant(
                Some(&function.function),
                format!("duplicate array storage slot `{}`", slot.identity),
            ));
        }
        let length = u64::from(slot.length);
        if length > MAX_ARRAY_BYTES {
            return Err(array_error(
                &function.function,
                format!(
                    "array storage slot `{}` has length {length}; limit is {MAX_ARRAY_BYTES}",
                    slot.identity
                ),
            ));
        }
        total = total.checked_add(length).ok_or_else(|| {
            array_error(
                &function.function,
                "inline array frame byte calculation overflowed",
            )
        })?;
    }
    if total > MAX_INLINE_ARRAY_FRAME_BYTES {
        return Err(array_error(
            &function.function,
            format!(
                "inline array frame uses {total} bytes; limit is {MAX_INLINE_ARRAY_FRAME_BYTES}"
            ),
        ));
    }
    Ok(total)
}

fn validate_flow<'a>(
    function: &'a FunctionCapacityInput,
    functions: &BTreeMap<&str, &FunctionCapacityInput>,
    strategy: AllocationStrategy,
) -> Result<(BTreeSet<&'a str>, bool, bool, bool), CapacityError> {
    let mut pending = vec![&function.execution];
    let mut nodes = 0usize;
    let mut callees = BTreeSet::new();
    let mut sites = BTreeSet::new();
    let mut has_local_copy = false;
    let mut has_local_stdin_read = false;
    let mut has_local_transcript_write = false;
    while let Some(flow) = pending.pop() {
        nodes = nodes.checked_add(1).ok_or_else(|| {
            invariant(
                Some(&function.function),
                "capacity flow node count overflowed",
            )
        })?;
        if nodes > MAX_FLOW_NODES {
            return Err(flow_node_bound(&function.function));
        }
        match flow {
            CapacityFlow::Empty => {}
            CapacityFlow::Sequence(children) | CapacityFlow::Alternative(children) => {
                pending.extend(children.iter().rev());
            }
            CapacityFlow::Call { site, callee } => {
                require_identity(site, Some(&function.function), "call site")?;
                require_identity(callee, Some(&function.function), "callee")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                if !functions.contains_key(callee.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("unknown capacity callee `{callee}`"),
                    ));
                }
                callees.insert(callee.as_str());
            }
            CapacityFlow::BytesCopy {
                site,
                conservative_payload_bytes,
            } => {
                require_identity(site, Some(&function.function), "bytes_copy site")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                if *conservative_payload_bytes > crate::byte_ops::MAX_OWNED_BYTE_VALUE_BYTES {
                    return Err(allocation_error(
                        &function.function,
                        format!(
                            "bytes_copy site `{site}` admits {conservative_payload_bytes} bytes; per-value limit is {}",
                            crate::byte_ops::MAX_OWNED_BYTE_VALUE_BYTES,
                        ),
                    ));
                }
                has_local_copy = true;
            }
            CapacityFlow::StdinRead {
                site,
                conservative_payload_bytes,
            } => {
                require_identity(site, Some(&function.function), "stdin_read site")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                if *conservative_payload_bytes > crate::byte_ops::MAX_OWNED_BYTE_VALUE_BYTES {
                    return Err(allocation_error(
                        &function.function,
                        format!(
                            "stdin_read site `{site}` admits {conservative_payload_bytes} bytes; per-value limit is {}",
                            crate::byte_ops::MAX_OWNED_BYTE_VALUE_BYTES,
                        ),
                    ));
                }
                has_local_stdin_read = true;
            }
            CapacityFlow::StdoutWrite { site, .. } => {
                require_identity(site, Some(&function.function), "stdout_write site")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                has_local_transcript_write = true;
            }
            CapacityFlow::StderrWrite { site, .. } => {
                require_identity(site, Some(&function.function), "stderr_write site")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                has_local_transcript_write = true;
            }
            CapacityFlow::StdoutAppend { site } => {
                require_identity(site, Some(&function.function), "stdout_append site")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                has_local_transcript_write = true;
            }
            CapacityFlow::StderrAppend { site } => {
                require_identity(site, Some(&function.function), "stderr_append site")?;
                if !sites.insert(site.as_str()) {
                    return Err(invariant(
                        Some(&function.function),
                        format!("duplicate capacity site `{site}`"),
                    ));
                }
                has_local_transcript_write = true;
            }
            CapacityFlow::FiniteOwnedLoop {
                iterations,
                condition,
                body,
            } => {
                if *iterations > MAX_BYTES_COPY_SITES {
                    return Err(invariant(
                        Some(&function.function),
                        "finite iterator bound exceeds the closed profile",
                    ));
                }
                pending.push(body);
                pending.push(condition);
            }
            CapacityFlow::FusedConstruction {
                producer,
                rows,
                width,
                condition,
                body,
            } => {
                fused::validate(
                    &function.function,
                    strategy,
                    producer,
                    *rows,
                    *width,
                    body,
                    nodes,
                )?;
                pending.push(body);
                pending.push(condition);
            }
            CapacityFlow::Loop { condition, body } => {
                pending.push(body);
                pending.push(condition);
            }
        }
    }
    Ok((
        callees,
        has_local_copy,
        has_local_stdin_read,
        has_local_transcript_write,
    ))
}

fn reverse_reachable<'a>(
    functions: &BTreeMap<&'a str, ValidatedFunction<'a>>,
    seed: impl Fn(&ValidatedFunction<'a>) -> bool,
) -> BTreeSet<&'a str> {
    let mut relevant = functions
        .iter()
        .filter_map(|(identity, item)| seed(item).then_some(*identity))
        .collect::<BTreeSet<_>>();
    loop {
        let before = relevant.len();
        for (identity, item) in functions {
            if item.callees.iter().any(|callee| relevant.contains(callee)) {
                relevant.insert(*identity);
            }
        }
        if relevant.len() == before {
            return relevant;
        }
    }
}

fn relevant_topological_order<'a>(
    functions: &BTreeMap<&'a str, ValidatedFunction<'a>>,
    relevant: &BTreeSet<&'a str>,
    diagnostic: CapacityDiagnostic,
) -> Result<Vec<&'a str>, CapacityError> {
    let mut indegree = relevant
        .iter()
        .map(|identity| (*identity, 0usize))
        .collect::<BTreeMap<_, _>>();
    for identity in relevant {
        for callee in &functions[identity].callees {
            if relevant.contains(callee) {
                let degree = indegree
                    .get_mut(callee)
                    .expect("relevant callee has indegree");
                *degree = degree.checked_add(1).ok_or_else(|| {
                    invariant(Some(identity), "capacity graph indegree overflowed")
                })?;
            }
        }
    }
    let mut ready = indegree
        .iter()
        .filter_map(|(identity, degree)| (*degree == 0).then_some(*identity))
        .collect::<BTreeSet<_>>();
    let mut order = Vec::with_capacity(relevant.len());
    while let Some(identity) = ready.pop_first() {
        order.push(identity);
        for callee in &functions[identity].callees {
            if !relevant.contains(callee) {
                continue;
            }
            let degree = indegree
                .get_mut(callee)
                .expect("relevant callee has indegree");
            *degree -= 1;
            if *degree == 0 {
                ready.insert(callee);
            }
        }
    }
    if order.len() != relevant.len() {
        let identity = indegree
            .iter()
            .find_map(|(identity, degree)| (*degree != 0).then_some(*identity))
            .expect("incomplete topological order has a cycle member");
        let detail = match diagnostic {
            CapacityDiagnostic::Array => "call-graph cycle can reach nonzero inline array storage",
            CapacityDiagnostic::Allocation => "bytes_copy executable closure is cyclic",
            CapacityDiagnostic::Transcript => "transcript-write executable closure is cyclic",
            CapacityDiagnostic::Invariant => unreachable!(),
        };
        return Err(CapacityError {
            diagnostic,
            function: Some(identity.to_owned()),
            detail: detail.to_owned(),
            witness_help: (diagnostic == CapacityDiagnostic::Transcript)
                .then(|| witnesses::cycle(functions, &indegree, identity))
                .flatten(),
        });
    }
    Ok(order)
}

fn fold_flow(
    flow: &CapacityFlow,
    mode: FoldMode,
    function: &str,
    summaries: &BTreeMap<String, FunctionCapacitySummary>,
    inputs: &BTreeMap<&str, &FunctionCapacityInput>,
) -> Result<(u64, AllocationSummary, TranscriptSummary), CapacityError> {
    enum Frame<'a> {
        Enter(&'a CapacityFlow),
        Finish(&'a CapacityFlow, usize),
    }
    let mut frames = vec![Frame::Enter(flow)];
    let mut values = Vec::<(u64, AllocationSummary, TranscriptSummary)>::new();
    while let Some(frame) = frames.pop() {
        match frame {
            Frame::Enter(node) => match node {
                CapacityFlow::Empty => values.push((
                    0,
                    AllocationSummary::default(),
                    TranscriptSummary::default(),
                )),
                CapacityFlow::Call { callee, .. } => {
                    let summary = &summaries[callee];
                    let mut transcript_paths = summary.transcript_paths.clone();
                    for path in &mut transcript_paths {
                        let direct = path
                            .stdout_append_sites
                            .checked_add(path.stderr_append_sites)
                            .ok_or_else(|| {
                                transcript_error(function, "append site count overflowed")
                            })?;
                        path.indirect_append_sites = path
                            .indirect_append_sites
                            .checked_add(direct)
                            .ok_or_else(|| {
                                transcript_error(function, "indirect append site count overflowed")
                            })?;
                    }
                    values.push((
                        summary.active_array_call_path_bytes,
                        AllocationSummary {
                            sites: summary.bytes_copy_sites,
                            stdin_sites: summary.stdin_read_sites,
                            payload_bytes: summary.owned_byte_payload_bytes,
                            fused: summary.fused_backing_events,
                        },
                        TranscriptSummary {
                            paths: transcript_paths,
                        },
                    ));
                }
                CapacityFlow::BytesCopy {
                    conservative_payload_bytes,
                    ..
                } => values.push((
                    0,
                    AllocationSummary {
                        sites: 1,
                        stdin_sites: 0,
                        payload_bytes: *conservative_payload_bytes,
                        fused: 0,
                    },
                    TranscriptSummary::default(),
                )),
                CapacityFlow::StdinRead {
                    conservative_payload_bytes,
                    ..
                } => values.push((
                    0,
                    AllocationSummary {
                        sites: 0,
                        stdin_sites: 1,
                        payload_bytes: *conservative_payload_bytes,
                        fused: 0,
                    },
                    TranscriptSummary::default(),
                )),
                CapacityFlow::StdoutWrite { source, .. } => {
                    values.push((
                        0,
                        AllocationSummary::default(),
                        TranscriptSummary {
                            paths: vec![TranscriptPath {
                                stdout_sites: 1,
                                stderr_sites: 0,
                                stdout_append_sites: 0,
                                stderr_append_sites: 0,
                                indirect_append_sites: 0,
                                sources: vec![*source],
                            }],
                        },
                    ));
                }
                CapacityFlow::StderrWrite { source, .. } => {
                    values.push((
                        0,
                        AllocationSummary::default(),
                        TranscriptSummary {
                            paths: vec![TranscriptPath {
                                stdout_sites: 0,
                                stderr_sites: 1,
                                stdout_append_sites: 0,
                                stderr_append_sites: 0,
                                indirect_append_sites: 0,
                                sources: vec![*source],
                            }],
                        },
                    ));
                }
                CapacityFlow::StdoutAppend { .. } => values.push((
                    0,
                    AllocationSummary::default(),
                    TranscriptSummary {
                        paths: vec![TranscriptPath {
                            stdout_sites: 0,
                            stderr_sites: 0,
                            stdout_append_sites: 1,
                            stderr_append_sites: 0,
                            indirect_append_sites: 0,
                            sources: Vec::new(),
                        }],
                    },
                )),
                CapacityFlow::StderrAppend { .. } => values.push((
                    0,
                    AllocationSummary::default(),
                    TranscriptSummary {
                        paths: vec![TranscriptPath {
                            stdout_sites: 0,
                            stderr_sites: 0,
                            stdout_append_sites: 0,
                            stderr_append_sites: 1,
                            indirect_append_sites: 0,
                            sources: Vec::new(),
                        }],
                    },
                )),
                CapacityFlow::Sequence(children) | CapacityFlow::Alternative(children) => {
                    frames.push(Frame::Finish(node, children.len()));
                    frames.extend(children.iter().rev().map(Frame::Enter));
                }
                CapacityFlow::Loop { condition, body }
                | CapacityFlow::FiniteOwnedLoop {
                    condition, body, ..
                }
                | CapacityFlow::FusedConstruction {
                    condition, body, ..
                } => {
                    frames.push(Frame::Finish(node, 2));
                    frames.push(Frame::Enter(body));
                    frames.push(Frame::Enter(condition));
                }
            },
            Frame::Finish(node, child_count) => {
                let split = values.len().checked_sub(child_count).ok_or_else(|| {
                    invariant(Some(function), "capacity fold result stack underflowed")
                })?;
                let children = values.drain(split..).collect::<Vec<_>>();
                let alternative = matches!(node, CapacityFlow::Alternative(_));
                let mut array_bytes = 0u64;
                let mut allocation = AllocationSummary::default();
                let transcript = if alternative {
                    alternative_transcripts(function, &children)?
                } else {
                    sequence_transcripts(function, &children)?
                };
                for (child_array, child_allocation, _) in &children {
                    if alternative {
                        array_bytes = array_bytes.max(*child_array);
                        allocation.sites = allocation.sites.max(child_allocation.sites);
                        allocation.payload_bytes =
                            allocation.payload_bytes.max(child_allocation.payload_bytes);
                        allocation.stdin_sites =
                            allocation.stdin_sites.max(child_allocation.stdin_sites);
                        allocation.fused = allocation.fused.max(child_allocation.fused);
                    } else {
                        array_bytes = array_bytes.checked_add(*child_array).ok_or_else(|| {
                            array_error(function, "active array call-path calculation overflowed")
                        })?;
                        allocation.sites = allocation
                            .sites
                            .checked_add(child_allocation.sites)
                            .ok_or_else(|| {
                                allocation_error(function, "bytes_copy site count overflowed")
                            })?;
                        allocation.payload_bytes = allocation
                            .payload_bytes
                            .checked_add(child_allocation.payload_bytes)
                            .ok_or_else(|| {
                                allocation_error(function, "owned byte payload sum overflowed")
                            })?;
                        allocation.stdin_sites = allocation
                            .stdin_sites
                            .checked_add(child_allocation.stdin_sites)
                            .ok_or_else(|| {
                                allocation_error(function, "stdin_read site count overflowed")
                            })?;
                        allocation.fused = allocation
                            .fused
                            .checked_add(child_allocation.fused)
                            .ok_or_else(|| {
                                allocation_error(function, "fused backing event count overflowed")
                            })?;
                    }
                }
                if let CapacityFlow::FusedConstruction { rows, width, .. } = node {
                    // Callee allocation summaries exist only during this fold.
                    if matches!(mode, FoldMode::Allocation) {
                        allocation =
                            fused::charge(function, *rows, *width, &children[0].1, &children[1].1)?;
                    }
                }
                if let CapacityFlow::FiniteOwnedLoop { iterations, .. } = node {
                    let condition = children[0].1;
                    let body = children[1].1;
                    if condition.fused != 0 || body.fused != 0 {
                        return Err(invariant(
                            Some(function),
                            "fused construction cannot repeat inside a finite iterator",
                        ));
                    }
                    if condition.sites != 0 || condition.stdin_sites != 0 || body.stdin_sites != 0 {
                        return Err(allocation_error(function, "finite iterator allocation is outside the iteration-local scratch domain"));
                    }
                    allocation.sites = body.sites.checked_mul(*iterations).ok_or_else(|| {
                        allocation_error(function, "finite iterator allocation count overflowed")
                    })?;
                    allocation.payload_bytes = body
                        .payload_bytes
                        .checked_mul(u64::from(*iterations))
                        .ok_or_else(|| {
                            allocation_error(function, "finite iterator payload sum overflowed")
                        })?;
                    allocation.stdin_sites = 0;
                }
                if matches!(mode, FoldMode::Allocation)
                    && matches!(node, CapacityFlow::Loop { .. })
                    && (allocation.sites != 0 || allocation.stdin_sites != 0)
                {
                    return Err(allocation_error(
                        function,
                        "bytes_copy is reachable from a while condition or body",
                    ));
                }
                if matches!(mode, FoldMode::Transcript)
                    && matches!(
                        node,
                        CapacityFlow::Loop { .. }
                            | CapacityFlow::FiniteOwnedLoop { .. }
                            | CapacityFlow::FusedConstruction { .. }
                    )
                {
                    let condition = &children[0].2;
                    let body = &children[1].2;
                    if condition.paths.iter().any(TranscriptPath::has_output) {
                        let mut selected = transcript_error(
                            function,
                            "transcript output is reachable from a while condition",
                        );
                        let component = match node {
                            CapacityFlow::Loop { condition, .. }
                            | CapacityFlow::FiniteOwnedLoop { condition, .. }
                            | CapacityFlow::FusedConstruction { condition, .. } => {
                                condition.as_ref()
                            }
                            _ => unreachable!(),
                        };
                        selected.witness_help =
                            witnesses::loop_output(component, function, inputs, "condition");
                        return Err(selected);
                    }
                    if body.paths.iter().any(|path| {
                        path.stdout_sites != 0
                            || path.stderr_sites != 0
                            || path.indirect_append_sites != 0
                    }) {
                        let mut selected = transcript_error(
                            function,
                            "a while body may contain only direct runtime-bounded append output",
                        );
                        let component = match node {
                            CapacityFlow::Loop { body, .. }
                            | CapacityFlow::FiniteOwnedLoop { body, .. }
                            | CapacityFlow::FusedConstruction { body, .. } => body.as_ref(),
                            _ => unreachable!(),
                        };
                        selected.witness_help =
                            witnesses::loop_output(component, function, inputs, "body");
                        return Err(selected);
                    }
                }
                values.push((array_bytes, allocation, transcript));
            }
        }
    }
    if values.len() != 1 {
        return Err(invariant(
            Some(function),
            "capacity fold did not produce exactly one result",
        ));
    }
    Ok(values.pop().expect("capacity fold result count checked"))
}

fn alternative_transcripts(
    function: &str,
    children: &[(u64, AllocationSummary, TranscriptSummary)],
) -> Result<TranscriptSummary, CapacityError> {
    if children.is_empty() {
        return Ok(TranscriptSummary::default());
    }
    let mut paths = BTreeSet::new();
    for (_, _, transcript) in children {
        paths.extend(transcript.paths.iter().cloned());
        if paths.len() > MAX_FLOW_NODES {
            return Err(invariant(
                Some(function),
                "transcript alternative path set exceeds the compiler bound",
            ));
        }
    }
    Ok(TranscriptSummary {
        paths: paths.into_iter().collect(),
    })
}

fn sequence_transcripts(
    function: &str,
    children: &[(u64, AllocationSummary, TranscriptSummary)],
) -> Result<TranscriptSummary, CapacityError> {
    let mut paths = vec![TranscriptPath::default()];
    for (_, _, transcript) in children {
        let product = paths
            .len()
            .checked_mul(transcript.paths.len())
            .ok_or_else(|| invariant(Some(function), "transcript path product overflowed"))?;
        if product > MAX_FLOW_NODES {
            return Err(invariant(
                Some(function),
                "transcript sequence path set exceeds the compiler bound",
            ));
        }
        let mut next = BTreeSet::new();
        for prefix in &paths {
            for suffix in &transcript.paths {
                let mut sources = prefix.sources.clone();
                sources.extend_from_slice(&suffix.sources);
                sources.sort_unstable();
                next.insert(TranscriptPath {
                    stdout_sites: prefix
                        .stdout_sites
                        .checked_add(suffix.stdout_sites)
                        .ok_or_else(|| {
                            transcript_error(function, "stdout_write site count overflowed")
                        })?,
                    stderr_sites: prefix
                        .stderr_sites
                        .checked_add(suffix.stderr_sites)
                        .ok_or_else(|| {
                            transcript_error(function, "stderr_write site count overflowed")
                        })?,
                    stdout_append_sites: prefix
                        .stdout_append_sites
                        .checked_add(suffix.stdout_append_sites)
                        .ok_or_else(|| {
                            transcript_error(function, "stdout_append site count overflowed")
                        })?,
                    stderr_append_sites: prefix
                        .stderr_append_sites
                        .checked_add(suffix.stderr_append_sites)
                        .ok_or_else(|| {
                            transcript_error(function, "stderr_append site count overflowed")
                        })?,
                    indirect_append_sites: prefix
                        .indirect_append_sites
                        .checked_add(suffix.indirect_append_sites)
                        .ok_or_else(|| {
                            transcript_error(function, "indirect append site count overflowed")
                        })?,
                    sources,
                });
            }
        }
        paths = next.into_iter().collect();
    }
    Ok(TranscriptSummary { paths })
}

fn transcript_path_bytes(function: &str, path: &TranscriptPath) -> Result<u64, CapacityError> {
    let append_sites = path
        .stdout_append_sites
        .checked_add(path.stderr_append_sites)
        .ok_or_else(|| transcript_error(function, "append site count overflowed"))?;
    if append_sites != 0 {
        if path.stdout_sites != 0 || path.stderr_sites != 0 {
            return Err(transcript_error(
                function,
                "legacy transcript writes and runtime-bounded appends cannot share an executable path",
            ));
        }
        return Ok(MAX_COMBINED_TRANSCRIPT_BYTES);
    }
    let mut fixed = 0u64;
    let mut arguments = 0u64;
    let mut stdin = 0u64;
    let mut unknown = 0u64;
    for source in &path.sources {
        match source {
            TranscriptSource::Fixed(bytes) => {
                fixed = fixed.checked_add(*bytes).ok_or_else(|| {
                    transcript_error(function, "fixed transcript byte sum overflowed")
                })?;
            }
            TranscriptSource::CommandArguments => arguments += 1,
            TranscriptSource::Stdin => stdin += 1,
            TranscriptSource::Unknown => unknown += 1,
        }
    }
    if arguments > 1 {
        return Err(transcript_error(
            function,
            "one command-argument root is published more than once on an executable path",
        ));
    }
    if stdin > 1 {
        return Err(transcript_error(
            function,
            "one stdin root is published more than once on an executable path",
        ));
    }
    let dynamic = arguments + stdin + unknown;
    if unknown != 0 && path.sources.len() > 1 {
        return Err(transcript_error(
            function,
            "an unauthenticated slice root cannot share a transcript path",
        ));
    }
    if fixed != 0 && dynamic != 0 {
        return Err(transcript_error(
            function,
            "fixed bytes cannot be added to an invocation-bounded transcript root",
        ));
    }
    let bytes = if dynamic == 0 {
        fixed
    } else {
        MAX_COMBINED_TRANSCRIPT_BYTES
    };
    if bytes > MAX_COMBINED_TRANSCRIPT_BYTES {
        return Err(transcript_error(
            function,
            format!(
                "combined stdout/stderr path admits {bytes} bytes; limit is {MAX_COMBINED_TRANSCRIPT_BYTES}"
            ),
        ));
    }
    Ok(bytes)
}

impl TranscriptPath {
    fn has_output(&self) -> bool {
        self.stdout_sites != 0
            || self.stderr_sites != 0
            || self.stdout_append_sites != 0
            || self.stderr_append_sites != 0
    }
}

fn require_identity(
    identity: &str,
    function: Option<&str>,
    kind: &str,
) -> Result<(), CapacityError> {
    if identity.is_empty() || identity.contains('\0') {
        return Err(invariant(
            function,
            format!("{kind} identity must be nonempty and NUL-free"),
        ));
    }
    Ok(())
}

fn array_error(function: &str, detail: impl Into<String>) -> CapacityError {
    CapacityError {
        diagnostic: CapacityDiagnostic::Array,
        function: Some(function.to_owned()),
        detail: detail.into(),
        witness_help: None,
    }
}

fn allocation_error(function: &str, detail: impl Into<String>) -> CapacityError {
    CapacityError {
        diagnostic: CapacityDiagnostic::Allocation,
        function: Some(function.to_owned()),
        detail: detail.into(),
        witness_help: None,
    }
}

fn transcript_error(function: &str, detail: impl Into<String>) -> CapacityError {
    CapacityError {
        diagnostic: CapacityDiagnostic::Transcript,
        function: Some(function.to_owned()),
        detail: detail.into(),
        witness_help: None,
    }
}

fn invariant(function: Option<&str>, detail: impl Into<String>) -> CapacityError {
    CapacityError {
        diagnostic: CapacityDiagnostic::Invariant,
        function: function.map(str::to_owned),
        detail: detail.into(),
        witness_help: None,
    }
}

fn flow_node_bound(function: &str) -> CapacityError {
    invariant(
        Some(function),
        "capacity flow exceeds the compiler node bound",
    )
}

