fn joined_ownership_state(
    program: &dyn crate::cleanup::ReplayContext,
    function: &ResolvedFunction,
    states: &BTreeSet<PathState>,
    budget: &mut ReplayBudget,
) -> Result<(Vec<LivenessFlagId>, Vec<ReplayConditionalVariant>), Diagnostic> {
    let mut states = states.iter();
    let first = states
        .next()
        .ok_or_else(|| replay_error(function, "cleanup join has no incoming states"))?;
    storage::reserve_ownership_clone(function, first, budget)?;
    let mut live_order = first.live_order.clone();
    let mut conditional_variants = first.conditional_variants.clone();
    for state in states {
        live_order = join_live_orders(function, &live_order, &state.live_order, budget)?;
        conditional_variants = join_conditional_variants(
            program,
            function,
            &conditional_variants,
            &state.conditional_variants,
            budget,
        )?;
    }
    Ok((live_order, conditional_variants))
}

fn join_live_orders(
    function: &ResolvedFunction,
    left: &[LivenessFlagId],
    right: &[LivenessFlagId],
    budget: &mut ReplayBudget,
) -> Result<Vec<LivenessFlagId>, Diagnostic> {
    let mut flags = BTreeSet::new();
    for flag in left.iter().chain(right).copied() {
        storage::insert_set(function, &mut flags, flag, budget, "joined live flags")?;
    }
    let mut successors = BTreeMap::new();
    let mut indegree = BTreeMap::new();
    for flag in &flags {
        storage::insert_map(
            function,
            &mut successors,
            *flag,
            BTreeSet::new(),
            budget,
            "join successor lookup",
        )?;
        storage::insert_map(
            function,
            &mut indegree,
            *flag,
            0u32,
            budget,
            "join indegrees",
        )?;
    }
    for history in [left, right] {
        for pair in history.windows(2) {
            if storage::insert_set(
                function,
                successors
                    .get_mut(&pair[0])
                    .expect("joined replay flag is indexed"),
                pair[1],
                budget,
                "join successor edge",
            )? {
                *indegree
                    .get_mut(&pair[1])
                    .expect("joined replay flag is indexed") += 1;
            }
        }
    }
    let mut ready = BTreeSet::new();
    for (flag, degree) in &indegree {
        if *degree == 0 {
            storage::insert_set(function, &mut ready, *flag, budget, "join ready flags")?;
        }
    }
    budget.reserve_array::<LivenessFlagId>(function, flags.len(), "joined live history")?;
    let mut joined = Vec::with_capacity(flags.len());
    while let Some(flag) = ready.pop_first() {
        joined.push(flag);
        for successor in successors[&flag].iter().copied() {
            let degree = indegree
                .get_mut(&successor)
                .expect("joined replay flag is indexed");
            *degree -= 1;
            if *degree == 0 {
                storage::insert_set(function, &mut ready, successor, budget, "join ready flags")?;
            }
        }
    }
    if joined.len() != flags.len() {
        return Err(replay_error(
            function,
            "cleanup join has conflicting initialization histories",
        ));
    }
    Ok(joined)
}

fn join_conditional_variants(
    program: &dyn crate::cleanup::ReplayContext,
    function: &ResolvedFunction,
    left: &[ReplayConditionalVariant],
    right: &[ReplayConditionalVariant],
    budget: &mut ReplayBudget,
) -> Result<Vec<ReplayConditionalVariant>, Diagnostic> {
    let left_len = left.len();
    let right_len = right.len();
    let mut left_index = BTreeMap::new();
    let mut right_index = BTreeMap::new();
    for variant in left {
        storage::insert_map(
            function,
            &mut left_index,
            &variant.root,
            variant,
            budget,
            "left conditional roots",
        )?;
    }
    for variant in right {
        storage::insert_map(
            function,
            &mut right_index,
            &variant.root,
            variant,
            budget,
            "right conditional roots",
        )?;
    }
    let left = left_index;
    let right = right_index;
    if left.len() != left_len || right.len() != right_len || left.keys().ne(right.keys()) {
        return Err(replay_error(
            function,
            "cleanup join disagrees on conditional variant roots",
        ));
    }
    budget.reserve_array::<ReplayConditionalVariant>(
        function,
        left.len(),
        "joined conditional variants",
    )?;
    let mut joined = Vec::with_capacity(left.len());
    for (root, left_variant) in left {
        let right_variant = right[root];
        if left_variant.variant != right_variant.variant {
            return Err(replay_error(
                function,
                "cleanup join disagrees on conditional variant identity",
            ));
        }
        let mut left_cases = BTreeMap::new();
        let mut right_cases = BTreeMap::new();
        for (case, flags) in &left_variant.cases {
            storage::insert_map(
                function,
                &mut left_cases,
                case,
                flags,
                budget,
                "left conditional cases",
            )?;
        }
        for (case, flags) in &right_variant.cases {
            storage::insert_map(
                function,
                &mut right_cases,
                case,
                flags,
                budget,
                "right conditional cases",
            )?;
        }
        let domain = program
            .declarations()
            .variant_cases(&left_variant.variant)
            .ok_or_else(|| replay_error(function, "cleanup join variant has no closed domain"))?;
        let mut cases = Vec::new();
        for declared in domain {
            let flags = match (left_cases.get(&declared.id), right_cases.get(&declared.id)) {
                (Some(left), Some(right)) if left == right => *left,
                (Some(left), Some(right)) if left.is_empty() => *right,
                (Some(left), Some(right)) if right.is_empty() => *left,
                (Some(_), Some(_)) => {
                    return Err(replay_error(
                        function,
                        "cleanup join disagrees on conditional case payload liveness",
                    ));
                }
                (Some(flags), None) | (None, Some(flags)) => *flags,
                (None, None) => continue,
            };
            budget.reserve_vec(function, &mut cases, 1, "joined conditional cases")?;
            budget.reserve_array::<LivenessFlagId>(
                function,
                flags.len(),
                "joined conditional case flags",
            )?;
            budget.reserve_bytes(function, declared.id.as_str().len(), "joined case identity")?;
            cases.push((declared.id.clone(), flags.clone()));
        }
        let mut case_union = BTreeSet::new();
        for case in left_cases.keys().chain(right_cases.keys()) {
            storage::insert_set(
                function,
                &mut case_union,
                *case,
                budget,
                "joined case domain",
            )?;
        }
        if cases.len() != case_union.len() {
            return Err(replay_error(
                function,
                "cleanup join conditional state references a foreign case",
            ));
        }
        storage::reserve_variant_identity(function, root, &left_variant.variant, budget)?;
        joined.push(ReplayConditionalVariant {
            root: root.clone(),
            variant: left_variant.variant.clone(),
            cases,
        });
    }
    Ok(joined)
}

edits.new:
//! Precharge actual owned clone carriers. Shared identity Arcs allocate nothing
//! when cloned; projection/type/case containers retain their actual backing.
use super::*;
use std::mem::size_of;
pub(super) mod empty_renewals;
fn array<T>(count: usize) -> Option<usize> {
    count.checked_mul(size_of::<T>())
}
fn place(place: &CleanupPlace) -> Option<usize> {
    array::<DeclarationId>(place.projections.len())
}
fn ty(ty: &ResolvedType) -> Option<usize> {
    let mut stack = [None; crate::cache_codec::MAX_DEPTH + 1];
    stack[0] = Some((ty, 0usize));
    let mut len = 1;
    let mut bytes = 0usize;
    let mut work = 65_536usize;
    while len != 0 {
        let (value, next) = stack[len - 1]?;
        if next == 0 {
            work = work.checked_sub(1)?;
            let owned = match value {
                ResolvedType::Function { parameters, .. } => {
                    array::<ResolvedType>(parameters.len())?
                        .checked_add(size_of::<ResolvedType>())?
                }
                ResolvedType::Nominal { arguments, .. } => array::<ResolvedType>(arguments.len())?,
                ResolvedType::TypeParameter { .. } => 0,
                ResolvedType::Never
                | ResolvedType::Unit
                | ResolvedType::I64
                | ResolvedType::I32
                | ResolvedType::Char
                | ResolvedType::U8
                | ResolvedType::Usize
                | ResolvedType::F32
                | ResolvedType::F64
                | ResolvedType::Bool
                | ResolvedType::String
                | ResolvedType::ArrayU8(_)
                | ResolvedType::Bytes
                | ResolvedType::Str
                | ResolvedType::SliceU8
                | ResolvedType::StringMap
                | ResolvedType::OnceFunction
                | ResolvedType::OnceFunctionI64
                | ResolvedType::OnceFunctionI64Pair
                | ResolvedType::MutFunctionI64 => 0,
            };
            bytes = bytes.checked_add(owned)?;
        }
        let child = match value {
            ResolvedType::Function { parameters, result } => parameters
                .get(next)
                .or_else(|| (next == parameters.len()).then_some(result.as_ref())),
            ResolvedType::Nominal { arguments, .. } => arguments.get(next),
            _ => None,
        };
        if let Some(child) = child {
            if len == stack.len() {
                return None;
            }
            stack[len - 1] = Some((value, next + 1));
            stack[len] = Some((child, 0));
            len += 1;
        } else {
            len -= 1;
        }
    }
    Some(bytes)
}
fn staged(source: &StagedCopyResultSource) -> Option<usize> {
    match source {
        StagedCopyResultSource::Body { instance, .. } => ty(instance),
        StagedCopyResultSource::TryResidual {
            source_instance,
            target_instance,
            ..
        }
        | StagedCopyResultSource::TryOptionNone {
            source_instance,
            target_instance,
            ..
        } => ty(source_instance)?.checked_add(ty(target_instance)?),
    }
}
fn returned(source: &ReturnedSource) -> Option<usize> {
    match source {
        ReturnedSource::Scalar(_) => Some(0),
        ReturnedSource::Owned(value) => place(value),
    }
}
fn variant(value: &ReplayConditionalVariant) -> Option<usize> {
    value.cases.iter().try_fold(
        place(&value.root)?.checked_add(array::<(DeclarationId, Vec<LivenessFlagId>)>(
            value.cases.len(),
        )?)?,
        |n, (_, flags)| n.checked_add(array::<LivenessFlagId>(flags.len())?),
    )
}
fn state_bytes(state: &PathState) -> Option<usize> {
    let node = super::super::physical_storage::btree_node_upper::<
        ExpressionId,
        crate::cleanup_plan::renewal_history::RenewalHistory,
    >()?;
    let mut bytes = node
        .checked_add(array::<LivenessFlagId>(state.live_order.len())?)?
        .checked_add(array::<ReplayConditionalVariant>(
            state.conditional_variants.len(),
        )?)?;
    for history in state.renewals.values() {
        bytes = bytes
            .checked_add(node)?
            .checked_add(history.clone_payload_bytes()?)?;
    }
    for value in &state.conditional_variants {
        bytes = bytes.checked_add(variant(value)?)?;
    }
    if let Some(value) = &state.staged_copy_result {
        bytes = bytes.checked_add(staged(value)?)?;
    }
    if let Some(value) = &state.returned {
        bytes = bytes.checked_add(returned(value)?)?;
    }
    Some(bytes)
}
pub(in crate::cleanup_plan::replay) fn reserve_btree_node<K, V>(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    phase: &str,
) -> Result<(), Diagnostic> {
    if !budget.pays_allocations() {
        return Ok(());
    }
    budget.reserve_bytes(
        function,
        super::super::physical_storage::btree_node_upper::<K, V>().unwrap_or(usize::MAX),
        phase,
    )
}
pub(in crate::cleanup_plan::replay) fn reserve_state_clone(
    function: &ResolvedFunction,
    state: &PathState,
    budget: &mut ReplayBudget,
    phase: &str,
) -> Result<(), Diagnostic> {
    if !budget.pays_allocations() {
        return Ok(());
    }
    if state.staged_copy_result.is_some() {
        budget.reserve_array::<Option<(&ResolvedType, usize)>>(
            function,
            crate::cache_codec::MAX_DEPTH + 1,
            "clone type scratch",
        )?;
    }
    budget.reserve_bytes(function, state_bytes(state).unwrap_or(usize::MAX), phase)
}
pub(super) fn reserve_ownership_clone(
    function: &ResolvedFunction,
    state: &PathState,
    budget: &mut ReplayBudget,
) -> Result<(), Diagnostic> {
    if !budget.pays_allocations() {
        return Ok(());
    }
    let bytes = (|| {
        state.conditional_variants.iter().try_fold(
            array::<LivenessFlagId>(state.live_order.len())?.checked_add(array::<
                ReplayConditionalVariant,
            >(
                state.conditional_variants.len(),
            )?)?,
            |n, value| n.checked_add(variant(value)?),
        )
    })();
    budget.reserve_bytes(
        function,
        bytes.unwrap_or(usize::MAX),
        "joined ownership clone",
    )
}
pub(super) fn reserve_control_clone(
    function: &ResolvedFunction,
    state: &PathState,
    budget: &mut ReplayBudget,
) -> Result<(), Diagnostic> {
    if !budget.pays_allocations() {
        return Ok(());
    }
    if state.staged_copy_result.is_some() {
        budget.reserve_array::<Option<(&ResolvedType, usize)>>(
            function,
            crate::cache_codec::MAX_DEPTH + 1,
            "control clone type scratch",
        )?;
    }
    let bytes = (|| {
        let mut bytes = 0usize;
        if let Some(value) = &state.staged_copy_result {
            bytes = bytes.checked_add(staged(value)?)?;
        }
        if let Some(value) = &state.returned {
            bytes = bytes.checked_add(returned(value)?)?;
        }
        Some(bytes)
    })();
    budget.reserve_bytes(
        function,
        bytes.unwrap_or(usize::MAX),
        "ownership group control clone",
    )
}

pub(in crate::cleanup_plan::replay) fn insert_set<K: Ord>(
    function: &ResolvedFunction,
    target: &mut BTreeSet<K>,
    value: K,
    budget: &mut ReplayBudget,
    phase: &str,
) -> Result<bool, Diagnostic> {
    if target.contains(&value) {
        return Ok(false);
    }
    reserve_btree_node::<K, ()>(function, budget, phase)?;
    Ok(target.insert(value))
}
pub(in crate::cleanup_plan::replay) fn insert_map<K: Ord, V>(
    function: &ResolvedFunction,
    target: &mut BTreeMap<K, V>,
    key: K,
    value: V,
    budget: &mut ReplayBudget,
    phase: &str,
) -> Result<(), Diagnostic> {
    if !target.contains_key(&key) {
        reserve_btree_node::<K, V>(function, budget, phase)?;
    }
    target.insert(key, value);
    Ok(())
}

pub(super) fn reserve_variant_identity(
    function: &ResolvedFunction,
    root: &CleanupPlace,
    _id: &DeclarationId,
    budget: &mut ReplayBudget,
) -> Result<(), Diagnostic> {
    if !budget.pays_allocations() {
        return Ok(());
    }
    budget.reserve_bytes(
        function,
        place(root).unwrap_or(usize::MAX),
        "joined variant identity",
    )
}

// Count through the existing ordered leaf index before its exact Vec copy.
// Preserve the unknown-storage refusal before attempting any reservation.
pub(in crate::cleanup_plan::replay) fn validate_place(
    function: &ResolvedFunction,
    place: &CleanupPlace,
    known: &BTreeSet<StorageId>,
    leaves: &Leaves,
    budget: &mut ReplayBudget,
) -> Result<Vec<LivenessFlagId>, Diagnostic> {
    if !known.contains(&place.storage) {
        return super::super::validate_place(function, place, known, leaves);
    }
    if !budget.pays_allocations() {
        return super::super::validate_place(function, place, known, leaves);
    }
    let matches = |leaf: &super::super::Leaf| {
        leaf.place.storage == place.storage
            && leaf.place.projections.starts_with(&place.projections)
    };
    let count = leaves.values().filter(|leaf| matches(leaf)).count();
    if count == 0 {
        return Err(replay_error(
            function,
            "cleanup place has no droppable leaf",
        ));
    }
    budget.reserve_array::<LivenessFlagId>(function, count, "entry place leaves")?;
    let mut result = Vec::with_capacity(count);
    result.extend(
        leaves
            .iter()
            .filter_map(|(flag, leaf)| matches(leaf).then_some(*flag)),
    );
    Ok(result)
}
pub(super) fn storage_regions(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<BTreeMap<StorageId, CleanupRegionId>, Diagnostic> {
    let mut regions = BTreeMap::new();
    for region in &function.cleanup_plan.regions {
        for storage in &region.slots {
            if regions.contains_key(storage) {
                return Err(replay_error(
                    function,
                    "cleanup storage has multiple owning regions during replay",
                ));
            }
            reserve_btree_node::<StorageId, CleanupRegionId>(
                function,
                budget,
                "storage region index",
            )?;
            regions.insert(storage.clone(), region.id);
        }
    }
    Ok(regions)
}
