                    .insert(
                        param.name.clone(),
                        Binding {
                            contract_local: false,
                            traversal_row: None,
                            ty: param.ty.clone(),
                            mode: binding_mode,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: false,
                            mutable: false,
                            active_loans: BTreeSet::new(),
                            borrow_origin: None,
                        },
                    )
                    .is_some()
                {
                    diagnostics.push(error(
                        program,
                        "SPX-T102",
                        format!("duplicate parameter `{}`", param.name),
                        param.span,
                    ));
                }
            }

            for contract in &function.requires {
                contract.visit_calls(&mut |callee, span| {
                    if crate::host_io_ops::by_name(callee).is_some() {
                        diagnostics.push(error(
                            program,
                            "SPX-T269",
                            "stdout_write is not admitted in contracts",
                            span,
                        ));
                    }
                    if crate::command_io_ops::by_name(callee).is_some() {
                        diagnostics.push(error(
                            program,
                            "SPX-T270",
                            "command I/O operations are not admitted in contracts",
                            span,
                        ));
                    }
                });
                require_bool_with_signature(
                    program,
                    function,
                    contract,
                    &variables,
                    functions,
                    types,
                    None,
                    diagnostics,
                    "precondition",
                    signature_refusal::origin(program, template, function),
                );
            }

            let (body_value, refusal_view) = check_expr_with_signature_view(
                program,
                function,
                &function.body,
                &mut variables,
                functions,
                types,
                None,
                true,
                diagnostics,
                Some(&byte_helpers),
                fused_producer,
                signature_refusal::origin(program, template, function),
            );
