                    Statement::For {
                        item, values, body, ..
                    }
                    | Statement::ForBorrow {
                        item, values, body, ..
                    }
                    | Statement::ForOwn {
                        item, values, body, ..
                    } => {
                        check_omitted_generic_mappings(
                            program,
                            current,
                            values,
                            &mut scope,
                            functions,
                            types,
                            diagnostics,
                            next,
                        );
