                    current,
                    child,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::If {
            condition,
            then_branch,
            else_branch,
        } => {
            for child in [
                condition.as_ref(),
                then_branch.as_ref(),
                else_branch.as_ref(),
            ] {
                check_omitted_generic_mappings(
                    program,
                    current,
                    child,
                    bindings,
                    functions,
                    types,
                    diagnostics,
                    next,
                );
            }
        }
        ExprKind::ConstructRecord { fields, .. } | ExprKind::ConstructVariant { fields, .. } => {
            for field in fields {
