use semaprax::image_transport::{VNextPolicy, VNextSession};
use semaprax::project::{with_authenticated_project, ProjectCandidate, SemanticChange};
use serde_json::{json, Value};
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

static SERIAL: AtomicU64 = AtomicU64::new(0);
const OPERATIONS: [(&str, &str, usize, &str, &str, &str); 7] = [
    (
        "core.string.len",
        "string_len",
        1,
        "string",
        "borrow",
        "i64",
    ),
    (
        "core.string.concat",
        "string_concat",
        2,
        "string",
        "own",
        "string",
    ),
    (
        "core.string.is_empty",
        "string_is_empty",
        1,
        "string",
        "borrow",
        "bool",
    ),
    (
        "core.string.starts_with",
        "string_starts_with",
        2,
        "string",
        "borrow",
        "bool",
    ),
    (
        "core.string.contains",
        "string_contains",
        2,
        "string",
        "borrow",
        "bool",
    ),
    (
        "core.string.len_chars",
        "string_len_chars",
        1,
        "string",
        "borrow",
        "i64",
    ),
    (
        "core.string.from_char",
        "string_from_char",
        1,
        "char",
        "value",
        "string",
    ),
];
struct Fixture(PathBuf);
impl Fixture {
    fn new() -> Self {
        let root = std::env::temp_dir().join(format!(
            "spx-string-builtin-v5-{}-{}",
            std::process::id(),
            SERIAL.fetch_add(1, Ordering::Relaxed)
        ));
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("semaprax.toml"),
            r#"schema = "semaprax.project.v8"
name = "string-builtin-transport"
version = "1.0.0"
profile = "owned-data-api.v1"
entry = "string_calls.app"
sources = ["src/app.spx", "src/core.spx", "src/tests.spx"]
web_exports = ["string_calls.public"]
tests = ["string_calls.tests"]
"#,
        )
        .unwrap();
        for (path, source) in [
            (
                "src/app.spx",
                "module string_calls.app;\n@id(\"string_calls.main\") fn main()->i64 {0}\n",
            ),
            (
                "src/core.spx",
                r#"module string_calls.core;
@id("string_calls.work") fn work()->i64 {0}
@id("string_calls.truth") fn truth()->bool {false}
@id("string_calls.text") fn text()->string {"old"}
@id("string_calls.scalar") fn from_scalar(value:char)->string {"old"}
@id("string_calls.public") fn public_value()->i64 {0}
"#,
            ),
            (
                "src/tests.spx",
                "module string_calls.tests;\n@id(\"string_calls.test\") fn main()->i64 {0}\n",
            ),
        ] {
            let parsed = semaprax::parse(source, path).unwrap();
            std::fs::write(root.join(path), semaprax::format::canonical(&parsed)).unwrap();
        }
        Self(root.canonicalize().unwrap())
    }
    fn session(&self, diagnostics: bool) -> VNextSession {
        VNextSession::open(
            &self.0.join("semaprax.toml"),
            VNextPolicy {
                candidate_prepare: true,
                diagnostics,
                ..Default::default()
            },
        )
        .unwrap()
    }
    fn candidate(&self) -> ProjectCandidate {
        with_authenticated_project(&self.0.join("semaprax.toml"), |snapshot| {
            ProjectCandidate::open(snapshot.retain_revision(), snapshot.project_revision())
        })
        .unwrap()
    }
    fn bytes(&self) -> Vec<Vec<u8>> {
        [
            "semaprax.toml",
            "src/app.spx",
            "src/core.spx",
            "src/tests.spx",
        ]
        .iter()
        .map(|path| std::fs::read(self.0.join(path)).unwrap())
        .collect()
    }
}
impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}
fn call(session: &mut VNextSession, method: &str, mut params: Value) -> Value {
    if !method.starts_with("protocol/") {
        params["image_revision"] = json!(session.image_revision());
    }
    let request = json!({"jsonrpc":"2.0","id":1,"method":method,"params":params}).to_string();
    serde_json::from_slice(&session.handle_frame(request.as_bytes()).unwrap()).unwrap()
}
fn row_for<'a>(rows: &'a [Value], target: &str) -> &'a Value {
    rows.iter()
        .find(|row| row["target"] == target)
        .unwrap_or_else(|| panic!("the builtin catalogue publishes {target}"))
}
fn payload(response: Value) -> Value {
    assert!(response.get("error").is_none(), "{response}");
    response["result"]["payload"].clone()
}
fn metadata(catalog: &Value) {
    let rows = catalog["builtin_calls"].as_array().unwrap();
    // Fourteen byte operations, including bounded zeroing and the fixed-width/tagged writes,
    // and nine String-producing or String operations.
    assert_eq!(rows.len(), 23);
    assert!(rows[..14]
        .iter()
        .all(|row| row["evidence_owner"] == "compiler_byte_operations"));
    assert!(rows[14..]
        .iter()
        .all(|row| row["evidence_owner"] == "compiler_string_operations"));
    // The owned buffer operations publish their exact arity and the transfer that
    // makes one filled buffer have a single owner.
    let zeroed = row_for(rows, "core.bytes.zeroed");
    assert_eq!(zeroed["name"], "bytes_zeroed");
    assert_eq!(zeroed["arity"], 1);
    assert_eq!(zeroed["parameters"][0]["ownership"], "value");
    let bounded = row_for(rows, "core.bytes.zeroed-bounded");
    assert_eq!(bounded["name"], "bytes_zeroed_bounded");
    assert_eq!(bounded["arity"], 2);
    assert_eq!(bounded["parameters"][0]["ownership"], "value");
    assert_eq!(bounded["parameters"][1]["ownership"], "value");
    let set = row_for(rows, "core.bytes.set");
    assert_eq!(set["name"], "bytes_set");
    assert_eq!(set["arity"], 3);
    assert_eq!(set["parameters"][0]["ownership"], "own");
    assert_eq!(set["parameters"][1]["ownership"], "value");
    assert_eq!(set["parameters"][2]["ownership"], "value");
    let set5 = row_for(rows, "core.bytes.set5");
    assert_eq!(set5["name"], "bytes_set5");
    assert_eq!(set5["arity"], 7);
    assert_eq!(set5["parameters"][0]["ownership"], "own");
    assert!(set5["parameters"].as_array().unwrap()[1..]
        .iter()
        .all(|parameter| parameter["ownership"] == "value"));
    let set1_or5 = row_for(rows, "core.bytes.set1_or5_from_slice");
    assert_eq!(set1_or5["name"], "bytes_set1_or5_from_slice");
    assert_eq!(set1_or5["arity"], 5);
    assert_eq!(set1_or5["parameters"][0]["ownership"], "own");
    assert_eq!(set1_or5["parameters"][3]["ownership"], "borrow");
    let set1_or6_or48 = row_for(rows, "core.bytes.set1_or6_or48_from_slice");
    assert_eq!(set1_or6_or48["name"], "bytes_set1_or6_or48_from_slice");
    assert_eq!(set1_or6_or48["arity"], 5);
    assert_eq!(set1_or6_or48["parameters"][0]["ownership"], "own");
    assert_eq!(set1_or6_or48["parameters"][3]["ownership"], "borrow");
    for (index, (id, name, arity, ty, ownership, result)) in OPERATIONS.into_iter().enumerate() {
        let row = &rows[index + 14];
        assert_eq!(row.as_object().unwrap().len(), 9);
        assert_eq!(row["target"], id);
        assert_eq!(row["name"], name);
        assert_eq!(row["arity"], arity);
        assert_eq!(row["return_type_id"], result);
        assert_eq!(row["effects"], json!([]));
        assert_eq!(row["requires_full_candidate_validation"], true);
        let parameters = row["parameters"].as_array().unwrap();
        assert_eq!(parameters.len(), arity);
        for (index, parameter) in parameters.iter().enumerate() {
            assert_eq!(parameter.as_object().unwrap().len(), 5);
            assert_eq!(parameter["index"], index);
            assert_eq!(parameter["type_id"], ty);
            assert_eq!(parameter["ownership"], ownership);
            assert_eq!(parameter["type_family"], Value::Null);
        }
    }
}

